VBlank:					; DATA XREF: ROM:00000078o
		tst.b	(PlayCachedSoundVBlank).w
		bmi.s	@skip

@VBlankLoop:				; CODE XREF: VBlank+8Cj
		addq.b	#1,(word_FFAE10).l
		move	#$2700,sr
		movem.l	d0-a6,-(sp)
		tst.w	(Vint_delayWord).w
		beq.w	@TimerFinished
		subq.w	#1,(Vint_delayWord).w

@TimerFinished:				; CODE XREF: VBlank+18j
		tst.b	($FFFFFFFF).w
		beq.w	@NTSC
		move.l	#$B3,d7	; '³'   ; Set wait timer for PAL region

@PAL_WaitLoop:				; CODE XREF: VBlank:@PAL_WaitLoopj
		dbf	d7,@PAL_WaitLoop

@NTSC:					; CODE XREF: VBlank+24j
		bsr.w	PseudoRandomNumber
		bsr.w	RandomNumber	; Outputs random numbers to d0,	d1 and Random_number_buffer2
		move.b	#0,(SMPS_Running).w
		lea	(VDP_Control).l,a6
		movea.l	(VBlank_RunLoadedSub).w,a1
		jsr	(a1)		; DONE
		tst.b	(SMPS_Running).w
		bne.s	@SMPS_Running
		jsr	j_UpdateMusic

@SMPS_Running:				; CODE XREF: VBlank+50j
		clr.w	(VBlankVar2).w
		movem.l	(sp)+,d0-a6
		move	#$2500,sr
		rte
; ---------------------------------------------------------------------------

@skip:					; CODE XREF: VBlank+4j
		move.w	0(sp),(PlayCacheSoundVar1).w
		move.l	2(sp),(PlayCacheSoundVar2).w ; can't follow -- this is the address that was interrupted
		movem.w	d0-d3/d6,(word_FFFFE6C2).w
		movem.l	a0-a2,(dword_FFFFE6B4+2).w
		move.l	#loc_6C74,2(sp)
		move.b	#1,(PlayCachedSoundVBlank).w
		bra.w	@VBlankLoop
; End of function VBlank


