		moveq	#8,d1

@WillLoop3Times:			; CODE XREF: SomeCheckSumPassSub+2Cj
		move.b	(a1)+,(a0)
		nop
		nop
		nop
		nop
		nop
		nop
		nop
		nop
		move.b	(a0),d2
		and.b	(a1)+,d2
		beq.s	@WillAlwaysGetHere
		or.b	d1,d0

@WillAlwaysGetHere:			; CODE XREF: SomeCheckSumPassSub+26j
		lsr.b	#1,d1		; 8 divided by 2 equal 4
		bne.s	@WillLoop3Times
		clr.b	6(a0)
