Checksumcheck:	dc.b $40, $C		; DATA XREF: SomeCheckSumPassSub+4o
		dc.b $40, 3		; $40 and C = 0, $40 and 3 = 0,	0 and C	= 0, 0 and 3 = 0
		dc.b 0,	$C
		dc.b 0,	3

