RenderSprite:				; CODE XREF: LoadObjects+4Ap
					; LoadObjects+82p ...
		btst	#0,2(a0)	; Object Flags
		bne.s	RenderSprite_Return1 ; First flag was set so we	return
		btst	#1,2(a0)	; Object Flags (for ristar it is invisible when	hurt)
		beq.s	RenderSprite_Render

RenderSprite_Return1:			; CODE XREF: RenderSprite+6j
		rts
; ---------------------------------------------------------------------------

RenderSprite_Render:			; CODE XREF: RenderSprite+Ej
		movea.l	8(a0),a1	; Mappings offset
		moveq	#0,d0
		move.b	3(a0),d0	; Animation frame (byte)
		add.w	d0,d0
		adda.w	(a1,d0.w),a1	; Load mapping of current frame
		moveq	#0,d1
		move.b	(a1)+,d1	; Move first byte of current mappingframe to d1	for number of loops
		bmi.s	RenderSprite_Return2 ; If there	is no more (FF or -1) then return
		move.b	(a1)+,4(a0)	; Move second byte to ?? (frame	specific mappings defined setting) (byte)
		move.w	$2A(a0),d2	; Plane	fixed Y	pos (word) to d2
		move.w	$28(a0),d3	; Plane	fixed X	pos (word) to d3
