RenderSprite_ReadMappingsLoop:		; CODE XREF: RenderSprite+82j
		move.b	(a1)+,d0	; Move third byte to d0
		ext.w	d0		; Extend it to a word
		add.w	d2,d0		; And add the fixed Y pos to it
		move.w	d0,(a2)+	; Move this to a2 (Sprite word 0)
		move.b	(a1)+,(a2)+	; move fourth byte of mappings to a2 (Sprite byte 2)
		move.b	d6,(a2)+	; move d6 (SpriteNumber) to a2 (Sprite byte 3)
		move.w	(a1)+,d0	; Move word 4 (VRAM) to	d0 (byte 4 and 5) to d0
		add.w	$E(a0),d0	; Add VRAM offset to d0
		btst	#4,2(a0)	; Object flag (Only set	by Obj1A5_TelePorterToBack_6_2)
		bne.s	RenderSprite_TeleportedToBack
		ori.w	#$8000,d0

RenderSprite_TeleportedToBack:		; CODE XREF: RenderSprite+54j
