		move.b	(a1),d0		; Move byte 8 to d0 if not flags were set

RenderSprite_ObjectFlagsSet:		; CODE XREF: RenderSprite+62j
		addq.l	#1,a1		; Increase a1 by 1 so byte 8 or	9
		ext.w	d0		; Extend d0 (byte 6 or 7 of the	mappings)
		add.w	d3,d0		; Add plane fixed X pos	to d0
		andi.w	#$1FF,d0	; And immediate	d0 with	1FF (0000 0001 1111 1111)
		beq.s	RenderSprite_PlaneShiftedD0equ1FF ; IF equal then skip

loc_50C8:				; CODE XREF: RenderSprite+8Ej
					; RenderSprite+92j
