		addq.b	#1,d6		; Raise	counter	d6 by 1
		cmpi.w	#$50,d6	; 'P'   ; Have we done it 80 times?
		bhi.s	RenderSprite_Return2 ; Yes then	return
		dbf	d1,RenderSprite_ReadMappingsLoop ; Otherwise do	loop again

RenderSprite_Return2:			; CODE XREF: RenderSprite+26j
					; RenderSprite+80j
		rts
; ---------------------------------------------------------------------------

RenderSprite_PlaneShiftedD0equ1FF:	; CODE XREF: RenderSprite+76j
