		bra.s	loc_50C8
; ---------------------------------------------------------------------------

RenderSprite_ReadNegativeMappingsLoop:	; CODE XREF: RenderSprite+3Aj
					; RenderSprite+EAj
		move.b	(a1)+,d0	; Move third byte to d0
		ext.w	d0		; Extend it
		neg.w	d0		; And negate it	(flip it)
		moveq	#3,d4		; Set d4 to 3
		and.b	(a1),d4		; And it with the fourth byte
		addq.b	#1,d4		; Add 1
		lsl.w	#3,d4		; Then shift it	logically to the left 3	steps (multiply	by 8)
		sub.w	d4,d0		; Subtract that	from d0
		add.w	d2,d0		; And add the plane shifted Y pos to d0
		move.w	d0,(a2)+	; Add it to a2
		move.b	(a1)+,(a2)+	; Then add the fourth byte
		move.b	d6,(a2)+	; And add the counter to a2
		move.w	(a1)+,d0	; Then move byte fixe and six to d0
		add.w	$E(a0),d0	; Then add byte	5 and 6	with the VRAM offset
