AnimateSprite:				; CODE XREF: Obj1A0_BonusRound_2_1_Treasure+140p
					; Obj1A0_BonusRound_2_1_Treasure+15Ep ...
		move.w	6(a0),d0	; Animation number
		adda.w	(a1,d0.w),a1	; Animation source
		tst.b	(a1)		; Check	that we	have a source
		beq.s	AnimateSprite_NoAnimationSource
