		addq.b	#1,d0		; Increase it by 1
		cmp.b	1(a1),d0	; Check	if it matches what is in byte one of the animation
		bcs.s	AnimateSprite_NoNewFrame
		addq.b	#1,$D(a0)	; Increase current frame in animation by one
		moveq	#0,d0		; Reset	d0

AnimateSprite_NoNewFrame:		; CODE XREF: AnimateSprite+16j
		move.b	d0,$C(a0)	; Set animation	duration to the	value of d0
		moveq	#0,d0		; Reset	d0
		move.b	$D(a0),d0
		cmp.b	(a1),d0
		bcs.s	AnimateSprite_StillFramesToGo
		clr.b	$D(a0)
		moveq	#0,d0
		bset	#2,2(a0)

AnimateSprite_StillFramesToGo:		; CODE XREF: AnimateSprite+2Aj
		move.b	2(a1,d0.w),3(a0)
		rts
; ---------------------------------------------------------------------------

AnimateSprite_NoAnimationSource:	; CODE XREF: AnimateSprite+Aj
		clr.b	$D(a0)
		move.b	2(a1),3(a0)
		rts
; End of function AnimateSprite


; =============== S U B	R O U T	I N E =======================================


AnimateSpriteNoSourceCheck:		; CODE XREF: Obj181_DisplayIfNotMovingClearBit0InVarIfMoved+36p
					; Obj181_DisplayIfNotMovingClearBit1InVarIfMoved+36p ...
		move.w	6(a0),d0	; Animation number
		adda.w	(a1,d0.w),a1	; Animation source
		move.b	$C(a0),d0	; Timing?
		addq.b	#1,d0		; Add one
		cmp.b	1(a1),d0	; Compare with second byte of the animation for	timing
		bcs.s	AnimateSpriteNoSourceCheck_NoNewFrame ;	If it is lower or same then branch
		addq.b	#1,$D(a0)	; Else raise $D	by one
		moveq	#0,d0		; And clear $C in next step

AnimateSpriteNoSourceCheck_NoNewFrame:	; CODE XREF: AnimateSpriteNoSourceCheck+12j
		move.b	d0,$C(a0)	; Set $C to either same	or lower than the timing or clear it
		moveq	#0,d0
		move.b	$D(a0),d0	; Move $D number of frames to d0
		cmp.b	(a1),d0		; Compare it with the animations number	of frames
		bcs.s	AnimateSpriteNoSourceCheck_StillFramesToGo ; Branch if lower or	same
		clr.b	$D(a0)		; Set $D to zero
		moveq	#0,d0
		bset	#2,2(a0)	; Set bit 2 of the object flags
		rts
; ---------------------------------------------------------------------------

AnimateSpriteNoSourceCheck_StillFramesToGo: ; CODE XREF: AnimateSpriteNoSourceCheck+26j
		move.b	2(a1,d0.w),3(a0) ; Move	first animation	frame to byte 3	current	animation frame
		rts
; End of function AnimateSpriteNoSourceCheck


