; =============== S U B	R O U T	I N E =======================================

; Used for word	sized animation	such as	Ristar and checks for frame $69.

Ristar_AnimateSprite_CheckFor69:	; CODE XREF: Ristar_AnimateSpecial+22p
					; Ristar_ArmsPullsBody+8Ep ...
		move.w	6(a0),d0	; Animation number
		adda.w	(a1,d0.w),a1
		move.b	$C(a0),d0	; Animation timer
		addq.b	#1,d0
		cmp.b	1(a1),d0	; Check	if timer is the	same as	the animation timer
		bcs.s	AnimateSprite_CheckFor69_NoNewAnimFrame

AnimateSprite_CheckFor69_NewAnimFrame:	; CODE XREF: Ristar_AnimateSprite_CheckFor69+40j
					; Ristar_AnimateSprite_CheckFor69+48j
		moveq	#0,d0
		addq.b	#1,$D(a0)	; Add one to current frame

AnimateSprite_CheckFor69_NoNewAnimFrame: ; CODE	XREF: Ristar_AnimateSprite_CheckFor69+12j
		move.b	d0,$C(a0)	; Update animation timer
		moveq	#0,d0
		move.b	$D(a0),d0	; Move current frame to	d0
		cmp.b	(a1),d0		; Compare with frame in	animation
		bcc.s	AnimateSprite_CheckFor69_NoMoreAnimFramesToGo
		add.w	d0,d0
		move.w	2(a1,d0.w),d0	; Get frame2
		cmpi.w	#$69,d0	; 'i'   ; Is current frame $69
