		move.w	$46(a6),(LastLoadedObject).w ; Load address of previous	previous object	(grandparent) into temp
		move.w	(a1),d0		; Load object location in the object list to d0
		move.w	d0,$46(a6)	; Store	it in $46 parent
		beq.s	@skip		; If it	was empty then skip
		movea.w	d0,a5		; Else move address to a5
