; =============== S U B	R O U T	I N E =======================================

; Input:
; d0 tested and	used
; d4 gets moved	into FFE705
; d5 = VRAM
; d6 = btst #2
; d7 = loop counter
; a3 = Mapping
; Output: a1

LoadSingleLineNumber:			; CODE XREF: GameMode04_InitGamePlay+DEp
					; TextFunc2VRAM42E8+Ap	...
		lea	(HUD_1).l,a5
		move.w	d7,d1		; Move loop counter value into d1
		add.w	d1,d1		; Double it
		add.w	d1,d1		; And double it	again
		neg.w	d1		; Then negate it so we get correct negative index
		adda.w	d1,a5		; Add the address to a5	so we get either 1,10,100,1000,10000,100000,1000000,10000000,100000000,1000000000
		move.w	d7,d1		; Move loop counter value into d1 again
		addq.w	#2,d1		; Add 2	to it
		btst	#0,d1		; Test if bit 0	is set (odd) or	not (even)
		beq.s	LoadSingleLineNumber_EvenNumber
		addq.w	#1,d1		; It was odd so	we add 1 to get	even

LoadSingleLineNumber_EvenNumber:	; CODE XREF: LoadSingleLineNumber+18j
		neg.w	d1		; Negate it
		lea	(sp,d1.w),sp	; Load stack pointer (d1) to be	current	stack pointer
		movea.w	sp,a2		; Load the address in the stack	pointer	to a2
		movea.w	a2,a4		; Copy the address to a4
		move.w	d1,-(sp)	; Store	d1 to stack pointer -1
		move.b	d4,(byte_FFFFE705).w
		tst.l	d0
		beq.s	LoadSingleLineNumber_InputD0_Zero

LoadSingleLineNumber_CheckNextValue_Loop:
					; CODE XREF: LoadSingleLineNumber:LoadSingleLineNumber_LoopAgainj
		moveq	#0,d2
		move.l	(a5)+,d3	; Move first number into d3

LoadSingleLineNumber_SubtractD3_Again:	; CODE XREF: LoadSingleLineNumber+3Aj
		sub.l	d3,d0		; Subtract that	from input d0
		bcs.s	LoadSingleLineNumber_DoneCountingNumber	; If it	is lower then zero we move on
		addq.w	#1,d2		; Increase counter d2
		bra.s	LoadSingleLineNumber_SubtractD3_Again
; ---------------------------------------------------------------------------

LoadSingleLineNumber_DoneCountingNumber: ; CODE	XREF: LoadSingleLineNumber+36j
		add.l	d3,d0		; Add d3 value to d0 to	get above zero
		tst.b	(byte_FFFFE705).w
		bne.s	LoadSingleLineNumber_FFE705_Not_Zero
		tst.w	d2
		beq.s	LoadSingleLineNumber_NumberCount_Zero
		move.b	#1,(byte_FFFFE705).w ; We had at least one number so we	set FFE705 to 1

LoadSingleLineNumber_FFE705_Not_Zero:	; CODE XREF: LoadSingleLineNumber+42j
		addi.w	#$30,d2	; '0'   ; Increase d2 by $30
		move.b	d2,(a2)+	; Store	the value to a2	and increase the pointer
		bra.s	LoadSingleLineNumber_LoopAgain
; ---------------------------------------------------------------------------

LoadSingleLineNumber_NumberCount_Zero:	; CODE XREF: LoadSingleLineNumber+46j
		move.b	#$20,(a2)+ ; ' '

LoadSingleLineNumber_LoopAgain:		; CODE XREF: LoadSingleLineNumber+54j
		dbf	d7,LoadSingleLineNumber_CheckNextValue_Loop
		bra.s	LoadSingleLineNumber_AllValuesChecked
; ---------------------------------------------------------------------------

LoadSingleLineNumber_InputD0_Zero:	; CODE XREF: LoadSingleLineNumber+2Ej
		subq.w	#1,d7		; If input d0 was zero then we decrease	the loop counter by 1
		bmi.s	LoadSingleLineNumber_LoopCounter_Zero
		moveq	#$20,d0	; ' '   ; Loop counter was not zero so we set d0 to $20
		tst.w	d4
		beq.w	LoadSingleLineNumber_InputD4_Zero
		moveq	#$30,d0	; '0'   ; Input d4 was not zero so we set d0 to $30

LoadSingleLineNumber_InputD4_Zero:	; CODE XREF: LoadSingleLineNumber+68j
					; LoadSingleLineNumber+70j
		move.b	d0,(a2)+	; Move it into a2 and increase the pointer
		dbf	d7,LoadSingleLineNumber_InputD4_Zero

LoadSingleLineNumber_LoopCounter_Zero:	; CODE XREF: LoadSingleLineNumber+62j
		move.b	#$30,(a2)+ ; '0' ; Set a2 to $30 and increase the pointer

LoadSingleLineNumber_AllValuesChecked:	; CODE XREF: LoadSingleLineNumber+5Ej
		move.b	#$FF,(a2)+	; Set end of text value	to a2 and increase the pointer
		movea.w	a4,a2		; Restore the stack pointer address to new a2 (after text)
		bsr.w	LoadSingleLineText ; Input: a2 = bytes to d0 if	minus ,a3 = Mapping, d5	= VRAM,	d6 = btst #2
					; Output: a1
		move.w	(sp)+,d1	; Restore d1 from the stack pointer
		neg.w	d1		; Negate it
		lea	(sp,d1.w),sp	; Restore the stack pointer
		rts
; End of function LoadSingleLineNumber


