; Inputs d4 = input variable, d5 = input variable, d6 =	loop variable, a2 = check variables

SimillarToTextFunction5_Sub1:		; CODE XREF: SimillarToTextFunction5+2j
					; SimillarToTextFunction5+80p
		move.w	d6,d7		; Copy d6 to d7
		andi.w	#1,d7		; And with 1
		lea	(a2),a5		; Load check variables to a5
		lea	Source_Variable,a4
		lea	(VDP_Data).l,a6

SimillarToTextFunction5_Sub1_OuterLoop:	; CODE XREF: SimillarToTextFunction5_Sub1+52j
		lea	(a5),a2		; Load back check variables to a2
		move.w	d4,d0		; Move input variable d4 to d0
		jsr	(VDP_NormalizeD0Maybe).l ; Inputs:
					; D0: Anded FFFF long, Multiplied long 4, divided word 4, Ored $4000 word and swapped
		move.l	d0,4(a6)	; Store	the normalized value into 4(a6)

SimillarToTextFunction5_Sub1_InnerLoop:	; CODE XREF: SimillarToTextFunction5_Sub1+4Aj
		moveq	#0,d2		; Clear	d2
		moveq	#0,d0		; And d0
		move.b	(a2)+,d0	; Move check variable byte into	d0 (seems to be	either $20 or $FF)
		bmi.s	SimillarToTextFunction5_Sub1_A2_Byte_Negative
		subi.b	#$20,d0	; ' '   ; Subtract $20 before checking if the result is zero
		beq.s	SimillarToTextFunction5_Sub1_D0_EQ_Zero
		andi.b	#$3F,d0	; '?'   ; Else we and with 3F to filter out the highest two bits
		move.b	(a4,d0.w),d2	; Load source variable to d2
		tst.b	d6		; Test input d6
		beq.s	SimillarToTextFunction5_Sub1_Skip ; If it was zero then	we skip
		btst	#2,d6		; Test bit two of d6
		beq.s	SimillarToTextFunction5_Sub1_Bit2_D6_Zero
		asl.b	#2,d2		; Multiply d2 by 4
		bra.s	SimillarToTextFunction5_Sub1_Skip
