SimillarToTextFunction5_Sub1_Bit2_D6_Zero: ; CODE XREF:	SimillarToTextFunction5_Sub1+3Ej
		add.b	d2,d2		; Double d2

SimillarToTextFunction5_Sub1_Skip:	; CODE XREF: SimillarToTextFunction5_Sub1+38j
					; SimillarToTextFunction5_Sub1+42j
		add.w	d5,d2		; Add input d5 to d2

SimillarToTextFunction5_Sub1_D0_EQ_Zero: ; CODE	XREF: SimillarToTextFunction5_Sub1+2Cj
		move.w	d2,(a6)		; Move word d2 to a6
		bra.s	SimillarToTextFunction5_Sub1_InnerLoop
