Unusedsub_5E42_Score_NextNumberLoop:	; CODE XREF: Unusedsub_5E42_Score:Unusedsub_5E42_Score_LoopAgainj
		moveq	#0,d2		; Clear	d2
		move.l	(a1)+,d3	; Move score HUD_x to d3

Unusedsub_5E42_Score_CountNumber_Loop:	; CODE XREF: Unusedsub_5E42_Score+2Ej
		sub.l	d3,d0		; Subtract it from input d0
		bcs.s	Unusedsub_5E42_Score_FinishedCountingNumber
		addq.w	#1,d2		; It was not lower so we increase counter d2 and do another round of subtract
		bra.s	Unusedsub_5E42_Score_CountNumber_Loop
; ---------------------------------------------------------------------------

Unusedsub_5E42_Score_FinishedCountingNumber: ; CODE XREF: Unusedsub_5E42_Score+2Aj
		add.l	d3,d0		; We add back d3 to d0 since it	was below zero
		tst.b	(byte_FFFFE705).w
		bne.s	Unusedsub_5E42_Score_Not_Zero
		tst.w	d2
		beq.s	Unusedsub_5E42_Score_NumberWasAZero
		move.b	#1,(byte_FFFFE705).w ; At least	two digit score	so we set it to	1

Unusedsub_5E42_Score_Not_Zero:		; CODE XREF: Unusedsub_5E42_Score+36j
		add.w	d5,d2		; We increase d2 by value of d5	(d1+$17)
		move.w	d2,(a5)		; Set VDP_Data to that value
		bra.s	Unusedsub_5E42_Score_LoopAgain
; ---------------------------------------------------------------------------

Unusedsub_5E42_Score_NumberWasAZero:	; CODE XREF: Unusedsub_5E42_Score+3Aj
		move.w	d4,(a5)		; Move value of	d4 into	VDP_Data

Unusedsub_5E42_Score_LoopAgain:		; CODE XREF: Unusedsub_5E42_Score+46j
		dbf	d7,Unusedsub_5E42_Score_NextNumberLoop
		rts
; ---------------------------------------------------------------------------

Unusedsub_5E42_Score_Input_D0_EQ_Zero:	; CODE XREF: Unusedsub_5E42_Score+22j
		subq.w	#1,d7		; Go down one step of the loop counter

Unusedsub_5E42_Score_FillLoop:		; CODE XREF: Unusedsub_5E42_Score+54j
		move.w	d4,(a5)		; Move value of	d4 into	VDP_Data
		dbf	d7,Unusedsub_5E42_Score_FillLoop
		move.w	d5,(a5)		; Move value of	d5 (d1+$17) into VDP_Data
		rts
; End of function Unusedsub_5E42_Score


