GM04_RoundNumberToVDP_Data:		; CODE XREF: GameMode04_RoundScreen+44p
		lea	HUD_1,a1
		move.w	d7,d5		; Input	d7 to this sub happens to be 0
		add.w	d5,d5		; 0+0=0
		add.w	d5,d5		; 0+0=0
		neg.w	d5		; Negate 0 to get 0
		adda.w	d5,a1		; Add 0	to address a1 so we still get 1
		moveq	#$17,d5		; Set base address $17
		add.w	d1,d5		; Add input d1 in this sub $2000 to get	$2017
		lea	(VDP_Data).l,a5

GM04_RoundNumberToVDP_Data_OuterLoop:	; CODE XREF: GM04_RoundNumberToVDP_Data+2Aj
		moveq	#0,d2		; Clear	d2
		move.l	(a1)+,d3	; Move number 1	in this	sub to d3

GM04_RoundNumberToVDP_Data_InnerLoop:	; CODE XREF: GM04_RoundNumberToVDP_Data+22j
		sub.l	d3,d0		; Subtract 1 from d0 (Round number in this sub)
		bcs.s	GM04_RoundNumberToVDP_Data_ScoreNumberBelowZero
		addq.w	#1,d2		; Increase d2 to see what round	it is
		bra.s	GM04_RoundNumberToVDP_Data_InnerLoop
; ---------------------------------------------------------------------------

GM04_RoundNumberToVDP_Data_ScoreNumberBelowZero: ; CODE	XREF: GM04_RoundNumberToVDP_Data+1Ej
		add.l	d3,d0		; We got below 0 so we add 1 back up to	0
		add.w	d5,d2		; Add $2017 to the round value
		move.w	d2,(a5)		; Move $2017+round value to VDP_Data
		dbf	d7,GM04_RoundNumberToVDP_Data_OuterLoop	; In this sub we only do one loop so we	are done
		rts
; End of function GM04_RoundNumberToVDP_Data


