; =============== S U B	R O U T	I N E =======================================

; Inputs:
; D2 compared against $40
; D3 tested against zero
; Outputs:
; D0

Pal_MoveFullPal_FadeToNormal:		; CODE XREF: Pal_MoveFullPal_FadeAndSound+24p
					; Pal_LandSubroutineAdd4+16p ...
		moveq	#$3F,d4	; '?'   ; Set loop counter to loop 64 times
		lea	(Palette1ROM).w,a0
		lea	(FadePalette1ROM).w,a1

MovePal_FadeToNormal:			; CODE XREF: Pal_MoveFullUWPal_FadeToNormal+Aj
					; Pal_MoveHalfPal_FadeToNormal+Aj
		movem.l	d2-d5,-(sp)	; Push d2-d5 onto the stack
		moveq	#$40,d0	; '@'
		cmp.w	d0,d2		; Check	if d2 is $40
		bcs.s	Pal_MoveFullPal_FadeToNormal_D0_LT_D2 ;	If lower then branch
		tst.w	d3		; D2 was $40 or	higher so we chekc if d3 is more than zero
		beq.s	Pal_MoveFullPal_FadeToNormal_D3_Zero
		cmp.w	d2,d3		; Check	if d3 is d2
		bcs.s	Pal_MoveFullPal_FadeToNormal_D2_LT_D3 ;	BCS = BLO

Pal_MoveFullPal_FadeToNormal_D3_Zero:	; CODE XREF: Pal_MoveFullPal_FadeToNormal+16j
		move.w	d0,d2
		bra.s	Pal_MoveFullPal_FadeToNormal_D0_LT_D2
; ---------------------------------------------------------------------------

Pal_MoveFullPal_FadeToNormal_D2_LT_D3:	; CODE XREF: Pal_MoveFullPal_FadeToNormal+1Aj
		sub.w	d3,d2		; Subtract d3 from d2
		neg.w	d2		; Make d2 positive if it was negative
		add.w	d0,d2		; Add $40 to d2
		cmp.w	d2,d0		; Check	if d2 is $40 or	higher
		bcc.s	Pal_MoveFullPal_FadeToNormal_D0_LT_D2 ;	BCC = BHS
		moveq	#0,d2		; Otherwise we zero d2

Pal_MoveFullPal_FadeToNormal_D0_LT_D2:	; CODE XREF: Pal_MoveFullPal_FadeToNormal+12j
					; Pal_MoveFullPal_FadeToNormal+1Ej ...
		cmpi.w	#$40,d2	; '@'
		bne.s	Pal_MoveFullPal_FadeToNormal_Loop2
		lsr.w	#1,d4		; D2 was $40 so	divide the loop	counter	by two (half size)

Pal_MoveFullPal_FadeToNormal_Loop1:	; CODE XREF: Pal_MoveFullPal_FadeToNormal+36j
		move.l	(a1)+,(a0)+	; Move fade palette into normal	palette
		dbf	d4,Pal_MoveFullPal_FadeToNormal_Loop1
		bra.s	Pal_MoveFullPal_FadeToNormal_Return
; ---------------------------------------------------------------------------

Pal_MoveFullPal_FadeToNormal_Loop2:	; CODE XREF: Pal_MoveFullPal_FadeToNormal+30j
					; Pal_MoveFullPal_FadeToNormal+5Aj
		move.w	(a1)+,d0	; Move fade palette byte to d0 and increment
		rol.w	#4,d0		; Round	d0 left	4 steps	BGR0 becomes GR0B
		moveq	#0,d3		; Clear	d3
		moveq	#2,d5		; Set loop3 counter to 3 loops

Pal_MoveFullPal_FadeToNormal_Loop3:	; CODE XREF: Pal_MoveFullPal_FadeToNormal+54j
		lsl.w	#4,d3		; Multiply d3 by 16
		rol.w	#4,d0		; Round	d0 left	4 steps	GR0B becomes R0BG
		move.w	d0,d1		; Copy d0 to d1
		andi.w	#$F,d1		; And d1 with 1111
		mulu.w	d2,d1		; Multiply d2 with the anded R0BG
		lsr.w	#6,d1		; Shift	d1 right 6 steps (divide by 64)
		or.w	d1,d3		; Or the filtered and divided by 64 R0BG with d3
		dbf	d5,Pal_MoveFullPal_FadeToNormal_Loop3
		move.w	d3,(a0)+	; Load d3 to normal palette byte
		dbf	d4,Pal_MoveFullPal_FadeToNormal_Loop2

Pal_MoveFullPal_FadeToNormal_Return:	; CODE XREF: Pal_MoveFullPal_FadeToNormal+3Aj
		move.w	d2,d0
		movem.l	(sp)+,d2-d5
		rts
; End of function Pal_MoveFullPal_FadeToNormal


; =============== S U B	R O U T	I N E =======================================


Pal_MoveFullUWPal_FadeToNormal2:	; CODE XREF: Pal_UWSubroutine+24p
		moveq	#$3F,d2	; '?'   ; Loop 64 times
		lea	(UnderwaterFadePalette1ROM).w,a0
		lea	(UnderwaterPalette1ROM).w,a1
		movem.l	(FadeVar1).w,d0-d1

Pal_MoveFullUWPal_FadeToNormal2_Loop1:	; CODE XREF: Pal_MoveFullUWPal_FadeToNormal2:Pal_MoveFullUWPal_FadeToNormal2_Loop_againj
		roxl.l	#1,d1		; Round	FFE712 one step	to the right
		roxl.l	#1,d0		; Round	FFE70E one step	to the right
		bcc.s	Pal_MoveFullUWPal_FadeToNormal2_SkipColor ; D1 higher or same as d0
		move.w	(a0)+,(a1)+	; They were not	the same of d1 was smaller so we move move the fade palette color to the normal	palette
		bra.s	Pal_MoveFullUWPal_FadeToNormal2_Loop_again
; ---------------------------------------------------------------------------

Pal_MoveFullUWPal_FadeToNormal2_SkipColor: ; CODE XREF:	Pal_MoveFullUWPal_FadeToNormal2+14j
		addq.w	#2,a0		; We skip over this palette position
		addq.w	#2,a1		; We skip over this palette position

Pal_MoveFullUWPal_FadeToNormal2_Loop_again: ; CODE XREF: Pal_MoveFullUWPal_FadeToNormal2+18j
		dbf	d2,Pal_MoveFullUWPal_FadeToNormal2_Loop1
		rts
; End of function Pal_MoveFullUWPal_FadeToNormal2


; =============== S U B	R O U T	I N E =======================================


Pal_MoveHalfPal_FadeToNormal2:		; CODE XREF: Pal_MoveHalfPal_NormalToFade_TestVar40_2+18p
