Pal_MoveFullPal_FadeToNormal2_Loop1:	; CODE XREF: Pal_MoveFullPal_FadeToNormal2:Pal_MoveFullPal_FadeToNormal2_Loop_againj
		roxl.l	#1,d1
		roxl.l	#1,d0
		bcc.s	Pal_MoveFullPal_FadeToNormal2_SkipColor
		move.w	(a0)+,(a1)+
		bra.s	Pal_MoveFullPal_FadeToNormal2_Loop_again
; ---------------------------------------------------------------------------

Pal_MoveFullPal_FadeToNormal2_SkipColor: ; CODE	XREF: Pal_MoveFullPal_FadeToNormal2+1Aj
		addq.w	#2,a0
		addq.w	#2,a1

Pal_MoveFullPal_FadeToNormal2_Loop_again: ; CODE XREF: Pal_MoveFullPal_FadeToNormal2+1Ej
		dbf	d2,Pal_MoveFullPal_FadeToNormal2_Loop1

Pal_MoveFullPal_FadeToNormal2_Return:	; CODE XREF: Pal_MoveFullPal_FadeToNormal2+6j
