Pal_MoveFullPal_FadeSpecial:		; CODE XREF: Pal_UnusedFunc1p
					; Pal_UnusedFunc2p
		bclr	#0,(SomeSpecialCameraVar).w ; Object flags:
					; 0: Check none	gameplay index
					; 1: Set at game mode 4
					; 2: Set at game mode 4_5
					; 3: Set at Obj05D_7 Obj05D_IceSpikesMatSpike_5_1
					; 4: Set at GM04_5_4_Round6_2_5
					; 5: Ristar knocked out
					; 6: Unused
					; 7: Unused
		move.w	(PaletteArrayVar).w,d0
		movem.l	(FadeVar1).w,d1-d2
		lea	(Palette1ROM).w,a0
		lea	(FadePalette1ROM).w,a1
		moveq	#$3F,d7	; '?'   ; Loop 64 times

Pal_MoveFullPal_FadeSpecial_Loop1:	; CODE XREF: Pal_MoveFullPal_FadeSpecial:Pal_MoveFullPal_FadeSpecial_Loop_againj
		roxl.l	#1,d2
		roxl.l	#1,d1
		bcs.s	Pal_MoveFullPal_FadeSpecial_Skip4Colors
		move.w	d0,d3		; Move palette array variable to d3
		lsr.w	#2,d3		; Divide d3 by 4 to get	it within 0-7 range
		add.w	d3,d3		; And double it	to get the correct variable from the array
		move.w	PaletteVarForFade(pc,d3.w),d3
		or.w	(a1)+,d3	; Or the fade color with the variable color
		move.w	d3,(a0)+	; And move the calculated color	to the normal palette
		bra.s	Pal_MoveFullPal_FadeSpecial_Loop_again
; ---------------------------------------------------------------------------

Pal_MoveFullPal_FadeSpecial_Skip4Colors: ; CODE	XREF: Pal_MoveFullPal_FadeSpecial+1Ej
		addq.l	#2,a0
		addq.l	#2,a1

Pal_MoveFullPal_FadeSpecial_Loop_again:	; CODE XREF: Pal_MoveFullPal_FadeSpecial+2Ej
		dbf	d7,Pal_MoveFullPal_FadeSpecial_Loop1
		rts
; End of function Pal_MoveFullPal_FadeSpecial

; ---------------------------------------------------------------------------
PaletteVarForFade:dc.w $EEE, $CCC, $AAA, $888, $666, $444, $222, 0

