Pal_MoveHalfPal_NormalToFade_Loop1:	; CODE XREF: Pal_MoveHalfPal_NormalToFade+Cj
		move.l	(a0)+,(a1)+
		dbf	d0,Pal_MoveHalfPal_NormalToFade_Loop1
		rts
