		add.l	d0,(a3)
		move.b	#1,(UpdatePointsFlag).w	; Set to 1 for pseudo number points or 2 for update points in hud using	fixed points
		move.l	#$98961C,d1	; 9999900
		cmp.l	(a3),d1
		bhi.s	loc_6A3E
		move.l	d1,(a3)

loc_6A3E:				; CODE XREF: Ristar_AddPoints+18j
					; Ristar_AddPoints+42j
		cmpi.b	#2,(Ristar_Difficulty).w ; 2 = Super (1	Star)
		beq.s	Ristar_AddPoints_Return
		btst	#6,(CheatCode1).w ; 6: MUSEUM (Boss Rush)
		bne.w	Ristar_AddPoints_Return	; If boss rush is active then return
		move.l	(a3),d0
		cmp.l	(dword_FFFFE570).w,d0
		bcs.s	Ristar_AddPoints_Return
		addi.l	#$7530,(dword_FFFFE570).w ; Add	30000
		bsr.w	Ristar_AddLife
		bra.s	loc_6A3E
