; =============== S U B	R O U T	I N E =======================================

; Inputs a1, d1, d2, d5	(0=FG, 1=BG)
; If selected byte in a1 is 0 or negative it returns FFFFA800 as a1 and	-1 as d0.
; Else it returns d0 = 0 and either FG/BG mapping as a1.

FGMap_Function1:			; CODE XREF: Check_FG_Map+Ep
					; Check_FG_Map+40p
		move.w	d1,d3		; Copy d1 to d3	(Xpos maybe)
		move.w	d2,d4		; Copy d2 to d4	(Ypos maybe)
		lsr.w	#8,d3		; Divide d3 by 256
		lsr.w	#2,d4		; Divide d2 by 4
		andi.w	#$FFC0,d4	; Filter away the lowest $40
		add.w	d3,d4		; Add the divided d3 by	the divided and	filtered d4
		moveq	#0,d0
		move.b	(a1,d4.w),d0	; Load the byte	of the position	of the d4 value	in a1 array
		beq.s	FGMap_Function1_Loads_A800_to_A1_FFFFFFF_to_D0
		bmi.s	FGMap_Function1_Loads_A800_to_A1_FFFFFFF_to_D0
		subq.w	#1,d0		; The loaded byte was not 0 or negative	so we decrease it by 1
		ror.w	#7,d0		; Then we roll it to the right 7 steps so the low 7 bits becomes the high byte 0000 0000 1111 1111 becomes 1111	1110 0000 0001
		move.w	d1,d3		; Copy d1 to d3	so it is the original again
		move.w	d2,d4		; Copy d2 to d4	so it is the original again
		lsr.w	#3,d3		; Divide d3 by 8
		andi.w	#$1E,d3		; Filter out 0000 0000 0001 1110 of d3
		add.w	d3,d0		; Add the result to d0
		add.w	d4,d4		; Double d4
		andi.w	#$1E0,d4	; Filter out 0000 0001 1110 0000
		add.w	d4,d0		; Add the result to d0 we now have AAAA	AAAB BBBC CCCA where d3	is C, d4 is B and loaded and rolled byte d0 is A
		lea	(FGMappings256x256_0).l,a1
		tst.w	d5
		beq.s	FGMap_Function1_FG_Selected
		movea.l	(BGMappings256x256_Address).w,a1

FGMap_Function1_FG_Selected:		; CODE XREF: FGMap_Function1+38j
		lea	(a1,d0.w),a1	; Load address of the selected mapping into a1
		moveq	#0,d0		; Reset	d0
		rts
; ---------------------------------------------------------------------------

FGMap_Function1_Loads_A800_to_A1_FFFFFFF_to_D0:	; CODE XREF: FGMap_Function1+14j
					; FGMap_Function1+16j
		lea	(ZeroOrNegative_FGMap256).w,a1
		moveq	#$FFFFFFFF,d0
		rts
; End of function FGMap_Function1


