		move.w	d4,(a6)		; Move d4 to a6	(VDP_Control)
		move.l	(a3)+,(a5)	; Move long value of a3	to a5 and increase a3
		add.w	d3,d0		; Add d3 (3) to	d0
		move.w	d0,(a6)		; Move d0 to a6
		move.w	d4,(a6)		; Move d4 to a6
