Camera_Setup_By_Level_ID_Byte:		; CODE XREF: GameMode04_RoundBlackScreen+17Ap
					; GM04_5_4_Round1_1_SetupLevelAndCamera+22p ...
		moveq	#0,d0
		move.b	(Level_ID_Byte).w,d0 ; 0: Round	1-1
					; 1: Round 1-2
					; 2: Round 1-3
					; 3: Round 2-1
					; 4: Round 2-2
					; 5: Round 2-3
					; 6: Round 3-1
					; 7: Round 3-2
					; 8: Round 3-3
					; 9: Round 4-1
					; A: Round 4-2
					; B: Round 4-3
					; C: Round 5-1
					; D: Round 5-2
					; E: Round 5-3
					; F: Round 6-1
					; 10: Round 6-2	(Room order 15,17,1A,19,1C,16,27,1B,1F,1E,(24),22,18,25,21,1D,(26),23)
					; 11: Round 6-3
					; 12: Round 7-1
					; 13: Round 7-2
					; 14: Round 7-3
					; 15: Exit 17
					; 16: Exit 27
					; 17: Exit 1A
					; 18: Exit 25
					; 19: Exit 1C
					; 1A: Exit 19
					; 1B: Exit 1F
					; 1C: Exit 16
					; 1D: Upper exit 26, lower exit	23
					; 1E: Upper exit 24, lower exit	18
					; 1F: Exit 1E
					; 20: Exit ?
					; 21: Exit 1D
					; 22: Exit 18
					; 23: End, left	exit 1D
					; 24: Exit 22
					; 25: Exit 21
					; 26: Exit 23
					; 27: Exit 1B
					; 28: Bonus Round 1-1
					; 29: Bonus Round 1-2
					; 2A: Bonus Round 2-1
					; 2B: Bonus Round 2-2
					; 2C: Bonus Round 3-1
					; 2D: Bonus Round 3-2
					; 2E: Bonus Round 4-1
					; 2F: Bonus Round 4-2
					; 30: Bonus Round 5-1
					; 31: Bonus Round 5-2
					; 32: Bonus Round 6-1
					; 33: Bonus Round 6-2
					; 34: xxx
					; 35: xxx
					; 36: xxx
					; 37: xxx
					; 38: xxx
					; 39: xxx
					; 3A: xxx
					; 3B: xxx
					; 3C: xxx
					; 3D: xxx
					; 3E: xxx
					; 3F:
		move.w	d0,d1
		lsl.l	#2,d0
		lea	(Camera_FG_BG_Xpos).l,a2
		lea	(Camera_FG_Xpos).w,a1 ;	Start of Camera_Object_Area
		move.w	#0,4(a1)	; Camera_FG_Ypos(a1)
		move.w	#0,$C(a1)	; Camera_BG_Ypos(a1)
		move.w	(a2,d0.w),0(a1)	; Camera_FG_Xpos(a1)
		move.w	2(a2,d0.w),8(a1) ; Camera_BG_Xpos(a1)
		tst.b	($FFFFFFFF).w	; PAL_Mode?
		beq.s	Camera_BG_Xpos_Positive	; NTSC so we branch
		moveq	#0,d2
		move.b	(Level_ID_Byte).w,d2 ; 0: Round	1-1
					; 1: Round 1-2
					; 2: Round 1-3
					; 3: Round 2-1
					; 4: Round 2-2
					; 5: Round 2-3
					; 6: Round 3-1
					; 7: Round 3-2
					; 8: Round 3-3
					; 9: Round 4-1
					; A: Round 4-2
					; B: Round 4-3
					; C: Round 5-1
					; D: Round 5-2
					; E: Round 5-3
					; F: Round 6-1
					; 10: Round 6-2	(Room order 15,17,1A,19,1C,16,27,1B,1F,1E,(24),22,18,25,21,1D,(26),23)
					; 11: Round 6-3
					; 12: Round 7-1
					; 13: Round 7-2
					; 14: Round 7-3
					; 15: Exit 17
					; 16: Exit 27
					; 17: Exit 1A
					; 18: Exit 25
					; 19: Exit 1C
					; 1A: Exit 19
					; 1B: Exit 1F
					; 1C: Exit 16
					; 1D: Upper exit 26, lower exit	23
					; 1E: Upper exit 24, lower exit	18
					; 1F: Exit 1E
					; 20: Exit ?
					; 21: Exit 1D
					; 22: Exit 18
					; 23: End, left	exit 1D
					; 24: Exit 22
					; 25: Exit 21
					; 26: Exit 23
					; 27: Exit 1B
					; 28: Bonus Round 1-1
					; 29: Bonus Round 1-2
					; 2A: Bonus Round 2-1
					; 2B: Bonus Round 2-2
					; 2C: Bonus Round 3-1
					; 2D: Bonus Round 3-2
					; 2E: Bonus Round 4-1
					; 2F: Bonus Round 4-2
					; 30: Bonus Round 5-1
					; 31: Bonus Round 5-2
					; 32: Bonus Round 6-1
					; 33: Bonus Round 6-2
					; 34: xxx
					; 35: xxx
					; 36: xxx
					; 37: xxx
					; 38: xxx
					; 39: xxx
					; 3A: xxx
					; 3B: xxx
					; 3C: xxx
					; 3D: xxx
					; 3E: xxx
					; 3F:
		cmpi.b	#$28,d2	; '('   ; Is level id $28
		bge.s	Level_ID_28_or_Greater
		move.l	#$A4100,d3
		btst	d2,d3		; Is it	round 1-1, 1-3,	2-3 or 4-3?
		bne.s	Camera_BG_Xpos_Positive

Level_ID_28_or_Greater:			; CODE XREF: Camera_Setup_By_Level_ID_Byte+3Cj
		subi.w	#$10,8(a1)	; Reduce Camera_BG_Xpos	by $10
		bpl.w	Camera_BG_Xpos_Positive
		move.w	#0,8(a1)	; If we	removed	too much so it got negative we zero it

Camera_BG_Xpos_Positive:		; CODE XREF: Camera_Setup_By_Level_ID_Byte+30j
					; Camera_Setup_By_Level_ID_Byte+46j ...
		cmpi.w	#$13,d1		; Is level id $13
		bne.s	Level_ID_Not_13
		move.w	#$10,$C(a1)	; Set Camera_BG_Ypos to	$10

Level_ID_Not_13:			; CODE XREF: Camera_Setup_By_Level_ID_Byte+5Cj
		cmpi.w	#$14,d1		; Is level ID $14
		bne.s	Level_ID_Not_14
		move.w	#$60,4(a1) ; '`' ; Set Camera_FG_Ypos to $60

Level_ID_Not_14:			; CODE XREF: Camera_Setup_By_Level_ID_Byte+68j
		cmpi.w	#$2A,d1	; '*'   ; Is level id $2A
		bne.s	Level_ID_Not_2A
		move.w	#$10,$C(a1)

Level_ID_Not_2A:			; CODE XREF: Camera_Setup_By_Level_ID_Byte+74j
		lea	(Camera2_FG_Xpos).w,a1 ; Start of camera 2 object area
		move.w	#0,4(a1)	; Set Camera2_FG_Ypos to 0
		move.w	#$6C0,0(a1)	; Set Camera2_FG_Xpos to $6C0 (1728)
		move.w	#0,$C(a1)	; Set Camera2_BG_Ypos to 0
		move.w	#$120,8(a1)	; Set Camera2_FG_Xpos to $120 (288)
		cmpi.w	#8,d1		; Is level ID 8
		bne.s	Level_ID_Not_8
		move.w	#$300,8(a1)	; Set Camera2_BG_Xpos to $300 (768)

Level_ID_Not_8:				; CODE XREF: Camera_Setup_By_Level_ID_Byte+9Cj
		rts
; End of function Camera_Setup_By_Level_ID_Byte

