		move.b	SoundArray(pc,d2.w),d0
		move.l	#$24924,d1	; 100 100 100 100 100 100 00 0000 0000 0000
		btst	d2,d1		; Is it	the first act in any of	the first 6 levels?
		beq.s	GameMode04_PlayRoundSound_PlaySound ; If not branch
