		beq.s	GameMode04_PlayRoundSound_PlaySound
		move.w	#$D,d0		; Same as level	7-2

GameMode04_PlayRoundSound_PlaySound:	; CODE XREF: GameMode04_PlayRoundSound+18j
					; GameMode04_PlayRoundSound+1Ej
