; =============== S U B	R O U T	I N E =======================================

; Input
; a3 to	move word into d0
; d2 bit to clear in FFE5A0
; Output
; a2 updated with added	sinewave value (-4,-2,-1,0,1,2,4 or 8)
; a3 updated value xxxxyyyy yyyyyyyy where y has been anded and	then decreased by one and or with xxxx that was	anded first

GM04_sub_BA06:				; CODE XREF: GM04_sub_B9D8+12p
					; GM04_sub_B9D8+28p
		move.w	(a3),d0		; Move value of	word_FFFFE5A4 into d0
		move.w	d0,d1		; Copy word into d1
		andi.w	#$FFF,d0	; And d0 0000 1111 1111	1111
		andi.w	#$F000,d1	; And d1 1111 0000 0000	0000
		subq.w	#1,d0		; Decrease d0 by 1
		bne.s	GM04_sub_BA06_D0_Not_Zero ; If it was zero we clear either bit 3 or 4 below
		bclr	d2,(SomeSpecialCameraVar).w ; Object flags:
					; 0: Check none	gameplay index
					; 1: Set at game mode 4
					; 2: Set at game mode 4_5
					; 3: Set at Obj05D_7 Obj05D_IceSpikesMatSpike_5_1
					; 4: Set at GM04_5_4_Round6_2_5
					; 5: Ristar knocked out
					; 6: Unused
					; 7: Unused

GM04_sub_BA06_D0_Not_Zero:		; CODE XREF: GM04_sub_BA06+Ej
		or.w	d1,d0		; Or d0	with 1111 0000 0000 0000
		move.w	d0,(a3)		; Store	result in a3
		andi.w	#7,d0		; Filter out the lowest	3 bits
		rol.w	#7,d1		; Round	7 steps	so ex 00000001 becomes 10000000
		add.w	d1,d0		; Add it to d0 so we get an index 0-63
		move.b	SinusWave(pc,d0.w),d0 ;	Get the	sinuswave byte
		ext.w	d0		; Extend it to a word
		add.w	d0,(a2)		; And add it to	the value in a2
		rts
; End of function GM04_sub_BA06

; ---------------------------------------------------------------------------
SinusWave:	dc.b 1,	0, $FF,	0, 1, 0, $FF, 0, 1, 2, 1, 0, $FF, $FE, $FF, 0
		dc.b 2,	0, $FE,	0, 2, 0, $FE, 0, 2, 4, 2, 0, $FE, $FC, $FE, 0
		dc.b 4,	0, $FC,	0, 4, 0, $FC, 0, 2, 4, 2, 0, 2,	4, 2, 0
		dc.b 1,	2, 1, 0, 1, 2, 1, 0, 4,	8, 4, 0, 4, 8, 4, 0

