BonusRoundStatus_VDPSetup:		; CODE XREF: ChkClrBonusRoundStatusBit0+24p
					; ChkClrBonusRoundStatusBit0+32p
		asl.w	#7,d1
		move.l	#$FF6000,d0
		add.l	d1,d0
		lea	(VDPCommandBuffer).w,a1
		jsr	(Encache68kVDPDMASourceRegs).l ; d0 = location
					; a1 = pointer to cache	entry; afterward
					;	   a1[0].l = location
					;	   a1[4].l = VDP command 1
					;	   a1[8].w = VDP command 2
					;	   a1 =	pointer	to next	cache entry (a1	+ $A)
		lea	(VDPCommandBuffer).w,a0
		move.w	(VDPSetupArrayBuffer81xx).w,d4
		bset	#4,d4
		move.w	d4,(a6)
		move	sr,-(sp)
		ori	#$700,sr
		move.w	#$100,(Z80BusReq).l ; D8 ( W)	0: BUSREQ CANCEL
					;	    1: BUSREQ REQUEST
					;    ( R)   0: CPU FUNCTION STOP ACCESSIBLE
					;	    1: FUNCTIONING

BonusRoundStatus_VDPSetup_Z80WaitLoop:	; CODE XREF: BonusRoundStatus_VDPSetup+38j
		btst	#0,(Z80BusReq).l ; D8 (	W)   0:	BUSREQ CANCEL
					;	    1: BUSREQ REQUEST
					;    ( R)   0: CPU FUNCTION STOP ACCESSIBLE
					;	    1: FUNCTIONING
		bne.s	BonusRoundStatus_VDPSetup_Z80WaitLoop
		move.l	#$94009340,(a6)
		move.l	4(a0),(a6)	; VDP command 1
		move.w	8(a0),(a6)	; VDP command 2
		ori.w	#$80,d5	; '€'
		move.w	d5,-(sp)
		swap	d5
		move.w	d5,(a6)

BonusRoundStatus_VDPSetup_Z80WaitLoop2:	; CODE XREF: BonusRoundStatus_VDPSetup+5Aj
		btst	#0,(Z80BusReq).l ; D8 (	W)   0:	BUSREQ CANCEL
					;	    1: BUSREQ REQUEST
					;    ( R)   0: CPU FUNCTION STOP ACCESSIBLE
					;	    1: FUNCTIONING
		bne.s	BonusRoundStatus_VDPSetup_Z80WaitLoop2
		move.w	(sp)+,(a6)
		move.w	#0,(Z80BusReq).l ; D8 (	W)   0:	BUSREQ CANCEL
					;	    1: BUSREQ REQUEST
					;    ( R)   0: CPU FUNCTION STOP ACCESSIBLE
					;	    1: FUNCTIONING
		move.w	(VDPSetupArrayBuffer81xx).w,(a6)
		swap	d5
		move.l	d5,(a6)
		movea.l	(a0),a0		; Jump one step?
		move.w	(a0),-4(a6)	; Next location
		move	(sp)+,sr
		rts
; End of function BonusRoundStatus_VDPSetup


