; FUNCTION CHUNK AT 00010D4A SIZE 00000062 BYTES
; FUNCTION CHUNK AT 00010F32 SIZE 00000022 BYTES
; FUNCTION CHUNK AT 00010FA8 SIZE 0000001C BYTES

		moveq	#0,d0
		move.b	(TempVarE63C).w,d0
		add.w	d0,d0
		add.w	d0,d0
		jmp	GameMode04_5_Sub1_2_1_Index(pc,d0.w) ; DONE
; ---------------------------------------------------------------------------

GameMode04_5_Sub1_2_1_Index:		; CODE XREF: GM4_RoundFadeIn_Sub1_Round1_2_FadeDarkLight+Aj
		bra.w	Round1_2_Set_Dark_or_Light_Palette ; 0
; ---------------------------------------------------------------------------
		bra.w	Round1_2_FadeToDark_Palette1 ; 1
; ---------------------------------------------------------------------------
		bra.w	Round1_2_FadeToDark_Palette2 ; 2
; ---------------------------------------------------------------------------
		bra.w	Round1_2_FadeToDark ; 3
; ---------------------------------------------------------------------------
		bra.w	Round1_2_Set_Dark_or_Light_Palette ; 4
; ---------------------------------------------------------------------------
		bra.w	Round1_2_FadeToLight_Palette1 ;	5
; ---------------------------------------------------------------------------
