; End of function GM4_RoundFadeIn_Sub1_Round1_2_FadeDarkLight


; =============== S U B	R O U T	I N E =======================================


Round1_2_Set_Dark_or_Light_Palette:	; CODE XREF: GM4_RoundFadeIn_Sub1_Round1_2_FadeDarkLight:GameMode04_5_Sub1_2_1_Indexj
					; GM4_RoundFadeIn_Sub1_Round1_2_FadeDarkLight+1Ej
		cmpi.w	#$1620,(Camera_min_Xpos_current).w
		bge.s	Round1_2_Set_Dark_or_Light_Palette_FadeToLightNearEnd ;	Camera min Xpos	current	is greater than	$1620 so we are	near the end and turn on the light again
		cmpi.w	#$1178,(Ristar_Xpos).w
		bge.w	Round1_2_Set_Dark_or_Light_Palette_FadeToDarkNearLightTree ; Ristars Xpos is greater than $1178	so we start fading to dark so the light	tree stands out

Round1_2_Set_Dark_or_Light_Palette_FadeToLightNearEnd:
					; CODE XREF: Round1_2_Set_Dark_or_Light_Palette+6j
		moveq	#1,d0
		move.b	d0,(TempVarE630).w ; Set fade to light
		cmp.b	(TempVarE631).w,d0 ; Was it set	earlier	as well?
		bne.s	Round1_2_Set_Dark_or_Light_Palette_NotTheSameEarlier ; Nope
		move.w	#1,(TempVarE63A).w ; Yes it was	so we set timer	to 1
		rts
; ---------------------------------------------------------------------------

Round1_2_Set_Dark_or_Light_Palette_FadeToDarkNearLightTree:
					; CODE XREF: Round1_2_Set_Dark_or_Light_Palette+Ej
		move.b	(TempVarE630).w,d0 ; Load the fade to light status
		cmp.b	(TempVarE631).w,d0 ; Was it also set earlier?
		bne.s	Round1_2_Set_Dark_or_Light_Palette_NotTheSameEarlier ; Nope
		tst.b	d0		; Are we going to fade to light?
		beq.s	Round1_2_Set_Dark_or_Light_Palette_NotFadeToLight ; Nope
		subq.w	#1,(TempVarE63A).w ; We	are fading to dark so we decrease the fade timer by 1
		bne.s	Round1_2_Set_Dark_or_Light_Palette_Return ; Timer was not done so we return
		move.b	#0,(TempVarE630).w ; We	have waited $258 (600) so we reset fade	to light status

Round1_2_Set_Dark_or_Light_Palette_Return:
					; CODE XREF: Round1_2_Set_Dark_or_Light_Palette+38j
		rts
; ---------------------------------------------------------------------------

Round1_2_Set_Dark_or_Light_Palette_NotFadeToLight:
					; CODE XREF: Round1_2_Set_Dark_or_Light_Palette+32j
		move.w	(SomethingWithPaletteFade).w,d0
		andi.w	#$1F,d0
		bne.s	Round1_2_Set_Dark_or_Light_Palette_Return2
		lea	(Round1_2_FadeIn_FadeOut_Palette).l,a0
		bchg	#0,(TempVarE638).w ; Bit change	so we alternate	between	dark and light colors
		beq.s	Round1_2_Set_Dark_or_Light_Palette_UseDarkColors
		addq.w	#6,a0		; It was set earlier so	we use light colors

Round1_2_Set_Dark_or_Light_Palette_UseDarkColors:
					; CODE XREF: Round1_2_Set_Dark_or_Light_Palette+58j
		lea	((Palette1ROM+$1A)).w,a1
		move.l	(a0)+,(a1)+	; Set colors $1A and $1C to either $A6A	and $A2A or $C8C and $C2C
		move.w	(a0)+,(a1)+	; Set color $1E	to either $AAA or $CCC

Round1_2_Set_Dark_or_Light_Palette_Return2:
					; CODE XREF: Round1_2_Set_Dark_or_Light_Palette+4Aj
		rts
; ---------------------------------------------------------------------------
Round1_2_FadeIn_FadeOut_Palette:dc.w $A6A, $A2A, $AAA
					; DATA XREF: Round1_2_Set_Dark_or_Light_Palette+4Co
		dc.w $C8C, $C2C, $CCC
; ---------------------------------------------------------------------------

Round1_2_Set_Dark_or_Light_Palette_NotTheSameEarlier:
					; CODE XREF: Round1_2_Set_Dark_or_Light_Palette+1Cj
					; Round1_2_Set_Dark_or_Light_Palette+2Ej
		move.b	d0,(TempVarE631).w ; It	was not	set earlier so we set it that it was now
		lsl.w	#2,d0		; Multiply the 1 by 4
		move.b	#3,(TempVarE63C).w ; Set main index to 3
		or.b	d0,(TempVarE63C).w ; Or	it with	4 so we	get an index 0-4
		jmp	Round1_2_Set_Dark_or_Light_Palette_Index(pc,d0.w)
; ---------------------------------------------------------------------------

Round1_2_Set_Dark_or_Light_Palette_Index:
					; CODE XREF: Round1_2_Set_Dark_or_Light_Palette+82j
		bra.w	Round1_2_Set_Dark_or_Light_Palette_InitFade
; ---------------------------------------------------------------------------
		bra.w	*+4
; ---------------------------------------------------------------------------

Round1_2_Set_Dark_or_Light_Palette_ResetFade:
					; CODE XREF: Round1_2_Set_Dark_or_Light_Palette+8Aj
		move.w	#$258,(TempVarE63A).w ;	Set timer to $258 (600)
		move.w	#0,(TempVarE632).w ; Reset fade	counter	1
		move.w	#0,(TempVarE634).w ; Reset fade	counter	2
		move.b	#0,(TempVarE636).w ; Reset fade	timer 1
		move.b	#0,(TempVarE637).w ; Reset fade	timer 2
		rts
; ---------------------------------------------------------------------------

Round1_2_Set_Dark_or_Light_Palette_InitFade:
					; CODE XREF: Round1_2_Set_Dark_or_Light_Palette:Round1_2_Set_Dark_or_Light_Palette_Indexj
		move.w	#9,(TempVarE632).w ; Set fade counter 1	to 9
		move.w	#7,(TempVarE634).w ; Set fade counter 2	to 7
		move.b	#$28,(TempVarE636).w ; '(' ; Set fade timer 1 to $28 (40)
		move.b	#0,(TempVarE637).w ; Set fade timer 2 to 0
		rts
; End of function Round1_2_Set_Dark_or_Light_Palette

