; =============== S U B	R O U T	I N E =======================================

; Inputs: d1 Xpos, d2 Ypos, a1.	Returns	FG Mapping as a1

LoadMap256_by_LevelLayout:		; CODE XREF: LevelLayoutLoadForeGroundXpos+4p
					; LevelLayoutLoadForeGroundXpos+32p ...
		move.w	d1,d3		; Move Xpos to d3
		move.w	d2,d4		; Move Ypos to d4
		lsr.w	#8,d3		; Divide Xpos by 256
		lsr.w	#2,d4		; Divide Ypos by 4
		andi.w	#$FFC0,d4	; Filter out so	we do not have the lowest 6 bits
		add.w	d3,d4		; Add Xpos divided by 256 to Ypos filtered
		moveq	#0,d0
		move.b	(a1,d4.w),d0	; Get the correct mapping
		beq.s	@D0_Zero_or_Negative
		bmi.s	@D0_Zero_or_Negative
		subq.w	#1,d0		; It was positive so we	decrease d0 by 1
		ror.w	#7,d0		; And round to the right 7 steps (swap almost all high byte for	low byte) 1111111100000000 will	be 0000000111111110
		move.w	d1,d3		; Move Xpos into d3
		move.w	d2,d4		; Move Ypos into d4
		lsr.w	#3,d3		; Divide Xpos by 8
		andi.w	#$1E,d3		; Filter out so	we only	have bits 1,2,3	and 4
		add.w	d3,d0		; Add the resulting Xpos (2-$1E) to d0
		add.w	d4,d4		; Double Ypos
		andi.w	#$1E0,d4	; Filter out so	we only	have bits 6,7,8	and 9
		add.w	d4,d0		; And add the resulting	Ypos to	d0
		lea	(FGMappings256x256_0).l,a1
		lea	(a1,d0.w),a1	; Return the correct mapping index
		rts
; ---------------------------------------------------------------------------

@D0_Zero_or_Negative:			; CODE XREF: LoadMap256_by_LevelLayout+14j
					; LoadMap256_by_LevelLayout+16j
		moveq	#0,d0
		moveq	#0,d0
		moveq	#0,d0
		moveq	#0,d0
		lea	(ZeroOrNegative_FGMap256).w,a1 ; Return	something_FGMap256
		rts
; End of function LoadMap256_by_LevelLayout


