		lea	(VDP_VRAM_Location_Base_Var).l,a2
		lsl.w	#3,d0		; Multiply d0 by 4
		moveq	#0,d1
		move.w	(a1,d0.w),d1	; Load first word can be 0-$20
		add.w	d1,d1		; Double the word for index next array
		move.w	(a2,d1.w),d1
