		swap	d0		; Swap high and	low
		ori.l	#$93009400,d0	; Or immediate with VRAM command 9300 and 9400
		move.l	d0,(LoadRistarUncDMA_VDPComm1_and_2).w ; Store VDP commands 1 and 2 in FFE55E
