					;	   a1[4].l = VDP command 1
					;	   a1[8].w = VDP command 2
					;	   a1 =	pointer	to next	cache entry (a1	+ $A)

Ristar_LoadUncRistarDMA_Return:		; CODE XREF: Ristar_LoadUncRistarDMA+10j
		rts
; End of function Ristar_LoadUncRistarDMA


