		asr.l	#8,d1		; Divide the result by 256
		move.w	d1,$1C(a0)	; Update Ristars air speed with	the result
		muls.w	$1A(a0),d2	; Multiply land	speed with calculated sine +$80
		asr.l	#8,d2		; Divide the result by 256
		move.w	d2,$1E(a0)	; Update Ristars Yspd with the result
		rts
