; =============== S U B	R O U T	I N E =======================================

; Returns d3 as	collision variable
; d0 Ristar collision body angle
; d5 Secondary collision index

RistarMovingDown_ChkCollision:		; CODE XREF: RistarInit_Sub8p
					; RistarSub2_Sub4+8p ...
		move.w	#0,$30(a0)	; Clear	Ristar_SecCollisionIndex
		move.l	#0,(CollisionHotspotLeftAngle).w
		move.l	#0,(CollisionHotspotRightAngle).w
		moveq	#6,d1
		moveq	#$10,d2
		add.w	$20(a0),d1
		add.w	$24(a0),d2
		lea	(CollisionHotspotLeftAngle).w,a3
		move.w	#$E,d7
		jsr	Collision_Down_PrimaryCollisionArray ; Takes d1	collision array	indexvar, d2 Ypos as inputs and	returns	d3 as collision	variable
					; 0(a3)	Ristar collision angles
					; 1(a3)	ColIndexStart
					; 2(a3)	Secondary collision index
		move.w	d3,-(sp)
		moveq	#$FFFFFFFA,d1
		moveq	#$10,d2
		add.w	$20(a0),d1
		add.w	$24(a0),d2
		lea	(CollisionHotspotRightAngle).w,a3
		jsr	Collision_Down_PrimaryCollisionArray ; Takes d1	collision array	indexvar, d2 Ypos as inputs and	returns	d3 as collision	variable
					; 0(a3)	Ristar collision angles
					; 1(a3)	ColIndexStart
					; 2(a3)	Secondary collision index
		move.w	(sp)+,d4
		cmp.w	d4,d3
		beq.s	@OldD3_EQ_NewD3
		blt.s	@ReturnRightHotspotAngle

@ReturnLeftHotspotAngle:		; CODE XREF: RistarMovingDown_ChkCollision+70j
					; RistarMovingDown_ChkCollision+80j
		moveq	#0,d6
		exg	d4,d3
		move.b	(CollisionHotspotLeftAngle).w,d0 ; Return Ristar collision body	angle
		move.w	(CollisionHotspotLeftSecCollIndex).w,d5
		rts
; ---------------------------------------------------------------------------

@ReturnRightHotspotAngle:		; CODE XREF: RistarMovingDown_ChkCollision+4Ej
					; RistarMovingDown_ChkCollision+78j ...
		moveq	#1,d6
		move.b	(CollisionHotspotRightAngle).w,d0 ; Return Ristar collision body angle
		move.w	(CollisionHotspotRightSecCollIndex).w,d5
		rts
; ---------------------------------------------------------------------------

@OldD3_EQ_NewD3:			; CODE XREF: RistarMovingDown_ChkCollision+4Cj
		cmpi.w	#$200,(CollisionHotspotLeftSecCollIndex).w
		beq.s	@ReturnLeftHotspotAngle
		cmpi.w	#$200,(CollisionHotspotRightSecCollIndex).w
		beq.s	@ReturnRightHotspotAngle
		btst	#0,$2C(a0)	; Is Ristar facing left?
		beq.s	@ReturnLeftHotspotAngle
		bra.w	@ReturnRightHotspotAngle
; End of function RistarMovingDown_ChkCollision


