; Input	d3, d4 for compare
; Return d6 1 for Ristar facing	right
; If d3	less than d4 or	facing left then d6 = 0	else d6	= 1
; Return d0 left or right hot spot angle and d5	either right or	left hot spot angle 2
; Return d3

Ristar_Jump_Collision_Check:		; CODE XREF: Ristar_GoingDownBranch_or_Cap_Xspd:Ristar_Jumpp
		moveq	#$FFFFFFF8,d1	; Xpos offset -8
		moveq	#$FFFFFFEC,d2	; Ypos offset -$13
		add.w	$20(a0),d1	; -8 + Xpos
		add.w	$24(a0),d2	; -$13 + Ypos
		lea	(CollisionHotspotLeftAngle).w,a3
		move.w	#$D,d7
		jsr	Collision_Up_PrimaryCollisionArray ; Inputs are	d1 Xpos, d2 Ypos
					; Returns d0 from collision array, uses	d1 for collision array indexvar.
					; 0(a3)	Third collision	array variable
					; 1(a2)	ColIndexStart
					; 2(a3)	Secondary collisiion index
					; Returns d3=0 No collision, other collision
		move.w	d3,-(sp)	; Store	collision variable on stack
		moveq	#8,d1		; Xpos offset 8
		moveq	#$FFFFFFEC,d2	; Ypos offset -$13
		add.w	$20(a0),d1
		add.w	$24(a0),d2
		lea	(CollisionHotspotRightAngle).w,a3
		jsr	Collision_Up_PrimaryCollisionArray ; Inputs are	d1 Xpos, d2 Ypos
					; Returns d0 from collision array, uses	d1 for collision array indexvar.
					; 0(a3)	Third collision	array variable
					; 1(a2)	ColIndexStart
					; 2(a3)	Secondary collisiion index
					; Returns d3=0 No collision, other collision
		move.w	(sp)+,d4	; Restore  previous collision variable (Xpos -8, Ypos -$13) to d4
		jmp	Collision_Routine7_HotSpot ; Input d3, d4 for compare
; End of function Ristar_Jump_Collision_Check ;	Return d6 1 for	Ristar facing right
					; If d3	less than d4 or	facing left then d6 = 0	else d6	= 1
					; Return d0 left or right hot spot angle and d5	either right or	left hot spot angle 2

