; Checks Ristars Xspd and caps it to $200 if needed

RistarSub2_ChkXspdWithCap200:		; CODE XREF: Ristar_In_Air+12p
					; Ristar_ArmsOut:Ristar_ArmsOut_Ristar_Not_In_Waterp ...
		tst.w	(word_FFAE64).l	; Set to -1 at Itamor 103_7 and	1 when Greedy loads orbs otherwise 0
		bne.w	FFAE64_Not_Zero
		move.w	(Ristar_X_Acceleration).w,d1
		move.w	(RistarMinXspdGrabbingItem).l,d2 ; Equal to $200
		move.b	(JoyPad1Held).w,d0
		btst	#3,d0		; Is right held?
		bne.s	RistarSub2_ChkXspdWithCap200_Right_Held
		btst	#2,d0		; Is left held?
		bne.s	RistarSub2_ChkXspdWithCap200_Left_Held

RistarSub2_ChkXspdWithCap200_Return:	; CODE XREF: RistarSub2_ChkXspdWithCap200+72j
					; RistarSub2_ChkXspdWithCap200+7Cj ...
		rts
; ---------------------------------------------------------------------------

RistarSub2_ChkXspdWithCap200_Right_Held: ; CODE	XREF: RistarSub2_ChkXspdWithCap200+1Cj
		btst	#2,$2C(a0)	; Do Ristar have his hands out?
		bne.s	RistarSub2_ChkXspdWithCap200_RistarsHandsOut
		btst	#1,$64(a0)	; Is level ID $F?
		beq.s	RistarSub2_ChkXspdWithCap200_Skip3 ; Nope so we	skip
		cmpi.b	#$C0,$2D(a0)	; Is Ristars angle $C0?
		beq.s	RistarSub2_ChkXspdWithCap200_RistarsAngle_C0_Right
		btst	#0,$2C(a0)	; Is Ristar facing left?
		bne.s	RistarSub2_ChkXspdWithCap200_Skip ; Yes

RistarSub2_ChkXspdWithCap200_RistarsAngle_C0_Right:
					; CODE XREF: RistarSub2_ChkXspdWithCap200+3Cj
		clr.b	$64(a0)		; Clear	$64()
		bclr	#0,$2C(a0)	; Clear	Ristar facing left
		bclr	#7,2(a0)	; Clear	Ristar facing left
		move.w	#$26,$60(a0) ; '&' ; Set next frame $26
		bra.s	RistarSub2_ChkXspdWithCap200_Skip
; ---------------------------------------------------------------------------

RistarSub2_ChkXspdWithCap200_Skip3:	; CODE XREF: RistarSub2_ChkXspdWithCap200+34j
		bclr	#0,$2C(a0)	; Clear	Ristar facing left

RistarSub2_ChkXspdWithCap200_RistarsHandsOut: ;	CODE XREF: RistarSub2_ChkXspdWithCap200+2Cj
		btst	#1,$50(a0)	; Has Ristar jumped after gliding on ice?
		beq.w	RistarSub2_ChkXspdWithCap200_Skip ; No
		tst.b	$36(a0)		; Check	Ristars	hurt invincible	timer
		beq.w	RistarSub2_ChkXspdWithCap200_Return ; Not invincible anymore

RistarSub2_ChkXspdWithCap200_Skip:	; CODE XREF: RistarSub2_ChkXspdWithCap200+44j
					; RistarSub2_ChkXspdWithCap200+5Cj ...
		move.w	$1C(a0),d0
		cmp.w	d2,d0		; Is Ristars XspdAir $200?
		bgt.w	RistarSub2_ChkXspdWithCap200_Return ; It was greater so	we return
		add.w	d1,d0		; Add Ristars acceleration to the Xspd
		cmp.w	d2,d0		; Is Ristars XspdAir $200?
		blt.s	RistarSub2_ChkXspdWithCap200_Set_Xspd ;	It was less so we set the speed	to that
		move.w	d2,d0		; Set XspdAir to $200

RistarSub2_ChkXspdWithCap200_Set_Xspd:	; CODE XREF: RistarSub2_ChkXspdWithCap200+84j
		move.w	d0,$1C(a0)
		rts
; ---------------------------------------------------------------------------

RistarSub2_ChkXspdWithCap200_Left_Held:	; CODE XREF: RistarSub2_ChkXspdWithCap200+22j
		btst	#2,$2C(a0)	; Do Ristar have his hands out?
		bne.s	RistarSub2_ChkXspdWithCap200_RistarsHandsOut2
		btst	#1,$64(a0)	; Is level ID $F?
		beq.s	RistarSub2_ChkXspdWithCap200_Skip4 ; Nope so we	skip
		cmpi.b	#$C0,$2D(a0)
		beq.s	RistarSub2_ChkXspdWithCap200_RistarsAngle_C0_Left
		btst	#0,$2C(a0)	; Is Ristar facing left?
		beq.s	RistarSub2_ChkXspdWithCap200_Skip2 ; No

RistarSub2_ChkXspdWithCap200_RistarsAngle_C0_Left:
					; CODE XREF: RistarSub2_ChkXspdWithCap200+A4j
		clr.b	$64(a0)		; Clear	$64()
		bset	#0,$2C(a0)	; Set Ristar facing left
		bset	#7,2(a0)	; Set Ristar facing left
		move.w	#$26,$60(a0) ; '&' ; Set next frame to $26
		bra.s	RistarSub2_ChkXspdWithCap200_Skip2
; ---------------------------------------------------------------------------

RistarSub2_ChkXspdWithCap200_Skip4:	; CODE XREF: RistarSub2_ChkXspdWithCap200+9Cj
		bset	#0,$2C(a0)	; Set Ristar facing left

RistarSub2_ChkXspdWithCap200_RistarsHandsOut2: ; CODE XREF: RistarSub2_ChkXspdWithCap200+94j
		btst	#1,$50(a0)	; Has Ristar jumped after gliding on ice?
		beq.w	RistarSub2_ChkXspdWithCap200_Skip2 ; Nope
		tst.b	$36(a0)		; Check	Ristars	hurt invincible	timer
		beq.w	RistarSub2_ChkXspdWithCap200_Return ; Not invincible anymore

RistarSub2_ChkXspdWithCap200_Skip2:	; CODE XREF: RistarSub2_ChkXspdWithCap200+ACj
