Ristar_AnimateSpecial:			; CODE XREF: Ristar_In_Air+2Ap
					; Ristar_LookingStunned+910j
		btst	#7,$2C(a0)	; Check	bit 7 of $2C currently unknown
		bne.w	@skip		; It was set so	we skip	to loading uncompressed	Ristar data
		tst.b	$5E(a0)		; Check	timer $5E
		beq.s	@TimerIsZero
		bmi.s	@TimedOut
		subq.b	#1,$5E(a0)	; It was still above zero so we	count down by one before loading the uncompressed Ristar data
		jmp	Ristar_LoadUncRistarDMA
; ---------------------------------------------------------------------------

@TimedOut:				; CODE XREF: Ristar_AnimateSpecial+10j
		lea	(Ristar_NormalPlay_Ani).l,a1
		jsr	(Ristar_AnimateSprite_CheckFor69).l ; Used for word sized animation such as Ristar and checks for frame	$69.
		jsr	Ristar_LoadUncRistarDMA
		bclr	#2,2(a0)
		beq.s	@return
		clr.b	$5E(a0)		; Animation is done so we clear	timer $5E

@return:				; CODE XREF: Ristar_AnimateSpecial+34j
		rts
; ---------------------------------------------------------------------------

@TimerIsZero:				; CODE XREF: Ristar_AnimateSpecial+Ej
		bclr	#7,2(a0)	; Clear	Ristar facing left
		btst	#0,$2C(a0)	; Is Ristar facing left?
		beq.s	@RistarNotFacingLeft
		bset	#7,2(a0)	; Set Ristar facing left

@RistarNotFacingLeft:			; CODE XREF: Ristar_AnimateSpecial+48j
		btst	#1,$64(a0)	; Is level id $F (6-1)?
		bne.w	@Level_id_7
		move.w	$1E(a0),d0	; Move Yspd to d0
		bpl.s	@RistarMovingUp
		move.w	#$23,$60(a0) ; '#' ; Set next frame to $23
		cmpi.w	#$FE00,d0
		blt.s	@Yspd_LT_FE00
		move.w	#$24,$60(a0) ; '$' ; Yspd was more than $FE00 so we set next frame to $24

@Yspd_LT_FE00:				; CODE XREF: Ristar_AnimateSpecial+6Aj
		bra.s	@skip
; ---------------------------------------------------------------------------

@RistarMovingUp:			; CODE XREF: Ristar_AnimateSpecial+5Ej
		move.w	#$25,$60(a0) ; '%' ; We set next frame to $25
		cmpi.w	#$100,d0
		blt.s	@skip		; Ristars Yspd was LT $100 so we skip over to loading the uncompressed data
		move.w	#$26,$60(a0) ; '&' ; It was higher than $100 so we set next frame to $26

@skip:					; CODE XREF: Ristar_AnimateSpecial+6j
					; Ristar_AnimateSpecial:@Yspd_LT_FE00j	...
		bra.w	Ristar_LoadUncRistarDMA
; ---------------------------------------------------------------------------

@Level_id_7:				; CODE XREF: Ristar_AnimateSpecial+56j
		moveq	#0,d0
		move.w	$1E(a0),d0	; Move Yspd to d0
		addi.w	#$100,d0	; Increase it by $100
		bpl.s	@RistarMovingUp2
		neg.w	d0		; He was still not moving up so	we negate it to	turn him around
		lsr.w	#8,d0		; Then divide the result by 256
		add.w	d0,d0		; And double the result	so we are in word sized	index
		lea	(Word_to_60_0).l,a1
		move.w	(a1,d0.w),$60(a0) ; Set	next frame to $BC, $B3,	$B3 or $B3
		bra.w	Ristar_LoadUncRistarDMA
; ---------------------------------------------------------------------------

@RistarMovingUp2:			; CODE XREF: Ristar_AnimateSpecial+94j
		clr.b	$64(a0)
		move.w	#$24,$60(a0) ; '$'
		bra.w	Ristar_LoadUncRistarDMA
; End of function Ristar_AnimateSpecial

