; =============== S U B	R O U T	I N E =======================================

; Slows	down Ristars Xspd and caps his Yspd if over $100

Ristar_In_Water_ChkSpeedMax100:		; CODE XREF: Ristar_In_Water_Sub1+5Ap
					; Ristar_In_Water_EnterWaterUpdate:@AlreadyRunp
		tst.w	$1C(a0)
		beq.s	@skip
		bpl.s	@RistarMovingRight
		addq.w	#8,$1C(a0)
		bmi.s	@skip
		move.w	#0,$1C(a0)
		bra.s	@skip
; ---------------------------------------------------------------------------

@RistarMovingRight:			; CODE XREF: Ristar_In_Water_ChkSpeedMax100+6j
		subq.w	#8,$1C(a0)
		bpl.s	@skip
		move.w	#0,$1C(a0)

@skip:					; CODE XREF: Ristar_In_Water_ChkSpeedMax100+4j
					; Ristar_In_Water_ChkSpeedMax100+Cj ...
		btst	#3,$4E(a0)	; Is Ristar floating on	the water surface?
		bne.s	@return		; He is	so we return
		move.w	$1E(a0),d0
		cmpi.w	#$100,d0
		bgt.s	@RistarYspd_GT_100
		subq.w	#8,$1E(a0)
		cmpi.w	#$FE00,$1E(a0)
		bgt.s	@return
		move.w	#$FE00,$1E(a0)

@return:				; CODE XREF: Ristar_In_Water_ChkSpeedMax100+28j
					; Ristar_In_Water_ChkSpeedMax100+3Ej
		rts
; ---------------------------------------------------------------------------

@RistarYspd_GT_100:			; CODE XREF: Ristar_In_Water_ChkSpeedMax100+32j
		lsr.w	#8,d0
		add.w	d0,d0
		lea	(Ristar_Yspd_Array).l,a1
		move.w	(a1,d0.w),d0
		sub.w	d0,$1E(a0)
		rts
; End of function Ristar_In_Water_ChkSpeedMax100

