@Speed_LE_C00:				; CODE XREF: Ristar_In_Water_ChkHurt_CapSpeed+1Cj
		addi.w	#$C00,d1	; Increase speed again to see if his speed got positive	(going down or right)
		bpl.s	@skip
		move.w	#$F400,(a1)	; If not we cap	his speed

@skip:					; CODE XREF: Ristar_In_Water_ChkHurt_CapSpeed+22j
					; Ristar_In_Water_ChkHurt_CapSpeed+28j
		cmpi.w	#$600,d0
