Ristar_In_Water_ChkXspdLand_Cap200:	; CODE XREF: Ristar_In_Water_MovingOnSurface+42p
		cmpi.w	#$200,$1A(a0)
		bls.s	@return		; If Ristars XspdLand is less or same as $200 then return
		moveq	#0,d0
		move.w	$1A(a0),d0	; Else we move it to d0
		subi.w	#$200,d0	; And decrease it by $200
		lsr.w	#7,d0		; Divide the result by 256
		cmpi.w	#5,d0		; Check	if the result is within	0-5
		bls.s	@Result_LS_5
		moveq	#5,d0		; Else we cap it to 5

@Result_LS_5:				; CODE XREF: Ristar_In_Water_ChkXspdLand_Cap200+18j
		add.w	d0,d0		; Double it to be word size
		lea	(Decrease_XspdLand_Var).l,a1
		move.w	(a1,d0.w),d0
		sub.w	d0,$1A(a0)	; Decrease Ristars XsdpLand by 4, 8, $10, $18 or $20
		cmpi.w	#$200,$1A(a0)
		bcc.s	@return		; Return if the	speed is higher	or same	as $200
		move.w	#$200,$1A(a0)	; Else we set the speed	to $200

@return:				; CODE XREF: Ristar_In_Water_ChkXspdLand_Cap200+6j
					; Ristar_In_Water_ChkXspdLand_Cap200+32j
		rts
