		andi.w	#$7F,d2	; ''
		bne.s	@BackupAngle_LT_80
		add.b	d1,d3		; Add current angle to the backup angle
		cmpi.b	#$80,d3
		bne.s	@skip		; The current angle was	not $80
		move.b	$2D(a0),(Ristar_UW_Angle_Backup).l ; It	was $80	so we set the backup angle to that
		bclr	#1,$4F(a0)	; Clear	ristar going down in the water (have him going up)
