; =============== S U B	R O U T	I N E =======================================

; Returns A as B80, 0 or 480

Obj0C7_SpinningSlotWheels_Sub1_Sub1:	; CODE XREF: Obj0C7_UnderWaterCurrentFanSpinningBlades_2_2_Sub1:@CounterMaxReachedp
		moveq	#0,d0
