		add.w	d1,$A(a1)	; Else we increase it with 20 or 40
		cmp.w	$A(a1),d2	; And compare again so we know we are not higher or same as 480	or B80
		bcc.s	@return		; If it	was then we return
		move.w	d2,$A(a1)	; Otherwise we set it to 480 or	B80

@return:				; CODE XREF: Obj0C7_SpinningSlotWheels_Sub1_Sub1+28j
					; Obj0C7_SpinningSlotWheels_Sub1_Sub1+32j ...
