RistarGliding_ChkJoyPad:		; CODE XREF: Ristar_NormalPlay:Ristar_NormalPlay_RistarGlidingOnIcep

; FUNCTION CHUNK AT 0001D53C SIZE 00000038 BYTES

		moveq	#$7F,d0	; ''
		and.b	$51(a0),d0
		add.w	d0,d0
		add.w	d0,d0
		jmp	RistarSub5_1_Index(pc,d0.w) ; DONE
; ---------------------------------------------------------------------------

RistarSub5_1_Index:			; CODE XREF: RistarGliding_ChkJoyPad+Aj
		bra.w	RistarGliding_StandingUp ; 0
; ---------------------------------------------------------------------------
		bra.w	RistarGliding_SittingDown ; 1
; ---------------------------------------------------------------------------
		bra.w	RistarGliding_SittingDownLong ;	2
; ---------------------------------------------------------------------------

RistarGliding_StandingUp:		; CODE XREF: RistarGliding_ChkJoyPad:RistarSub5_1_Indexj
		move.b	(JoyPad1Press).w,d0
		btst	#4,d0		; Is B pressed?
		bne.s	@B_Pressed
		andi.b	#$60,d0	; '`'   ; Is A or C pressed?
		bne.w	Ristar_Jump	; Yes
		move.b	(JoyPad1Held).w,d0
		btst	#3,d0		; Is Right held?
		bne.s	@Right_Held
		btst	#2,d0		; Is Left held?
		bne.s	@Left_Held
		rts
; ---------------------------------------------------------------------------

@B_Pressed:				; CODE XREF: RistarGliding_ChkJoyPad+22j
		move.b	#1,$51(a0)	; We have landed on a slippery surface on Ristars ass again so we set the status to 1
		move.b	#1,$52(a0)
		rts
; ---------------------------------------------------------------------------

@Right_Held:				; CODE XREF: RistarGliding_ChkJoyPad+34j
		bclr	#0,$2C(a0)	; Clear	Ristar facing left
		rts
; ---------------------------------------------------------------------------

@Left_Held:				; CODE XREF: RistarGliding_ChkJoyPad+3Aj
