@3B_EQ_E:				; CODE XREF: Ristar_UpdateLastTakenItem_XspdYspd+Cj
		clr.b	(byte_FFAEF4).l	; Either 0, 1 or 2 and only used in RistarSub17
		move.b	(JoyPad1Held).w,d0
		btst	#0,d0		; Is up	held?
		beq.s	@UpNotHeld
		move.b	#1,(byte_FFAEF4).l ; Either 0, 1 or 2 and only used in RistarSub17
		bra.s	@skip
; ---------------------------------------------------------------------------

@UpNotHeld:				; CODE XREF: Ristar_UpdateLastTakenItem_XspdYspd+40j
		btst	#1,$2C(a0)	; Is Ristar in the air?
		beq.s	@skip		; Nope
