		subi.w	#$320,d0	; Subtract $320	from it
		bmi.s	@skip		; If it	became negative	we skip
		cmpi.w	#$30,d0	; '0'   ; Check if Yspd is still higher than $30 (still going down)
		bhi.s	@skip		; If so	skip
		move.b	#2,(byte_FFAEF4).l ; Else set the var to 2

@skip:					; CODE XREF: Ristar_UpdateLastTakenItem_XspdYspd+4Aj
					; Ristar_UpdateLastTakenItem_XspdYspd+52j ...
		moveq	#0,d0
		move.b	(byte_FFAEF4).l,d0 ; Either 0, 1 or 2 and only used in RistarSub17
		move.b	d0,$14(a1)	; Update last taken items $14()	with the value of FFAEF4
		add.w	d0,d0		; Double the value
		add.w	d0,d0		; And double again
