		move.w	(a2,d0.w),d1	; Set d1 to Xspd
		move.w	2(a2,d0.w),d2	; Set d2 to Yspd
		bra.w	@updateXspdYspdLeftChk
; ---------------------------------------------------------------------------

@3B_EQ_F:				; CODE XREF: Ristar_UpdateLastTakenItem_XspdYspd+14j
		moveq	#0,d1
		move.w	(Obj0FF_CrystalKey_6_2_YposValue).l,d1
		sub.w	$20(a1),d1	; Subtract last	items Xpos from	Obj0FF Ypos value
		ext.l	d1		; Extend d1 to a long
		move.w	d1,d2		; Move lower word to d2
		beq.w	@SetXspdYspdDefault ; If it was	zero we	set default values
		bpl.s	@D2_Positive
		btst	#7,2(a0)	; Is Ristar facing left?
		beq.w	@SetXspdYspdDefault ; Nope
		neg.w	d2		; If so	we turn	him around
		bra.s	@skip2
; ---------------------------------------------------------------------------

@D2_Positive:				; CODE XREF: Ristar_UpdateLastTakenItem_XspdYspd+A2j
		btst	#7,2(a0)	; Is Ristar facing left
		bne.w	@SetXspdYspdDefault ; If so we do default values

@skip2:					; CODE XREF: Ristar_UpdateLastTakenItem_XspdYspd+B0j
		cmpi.w	#$80,d2	; '€'
		bhi.w	@SetXspdYspdDefault ; If d2 was	higher than $80	we do default values
		asl.w	#8,d1		; Else we multiply d1 by 256
		move.w	(Obj0FF_CrystalKey_6_2_YposSubValue).l,d2 ; Move Obj0FF	Ypos sub value to d2
		sub.w	$24(a1),d2	; Subtract last	items Ypos from	it
		asr.w	#4,d2		; And divide the result	by 16
		addq.w	#1,d2		; And add 1
		bpl.s	@Result_Positive
		moveq	#0,d2		; If it	was not	positive we clear d2

@Result_Positive:			; CODE XREF: Ristar_UpdateLastTakenItem_XspdYspd+D4j
