		cmpi.b	#$D,$3B(a0)	; Is Ristars pointer $3A sub $D?
		bne.s	@return
		movea.w	#$E660,a2	; Load FFFFE660	into a2
		moveq	#0,d0
		movea.w	$44(a0),a1	; Move last item into a1
		move.b	$17(a1),d0	; Load last items secondary subroutine counter into d0
		move.b	#0,(a2,d0.w)	; Set 0	on the byte corresponding to the secondary routine of the last item
		move.b	#$24,$16(a1) ; '$' ; Run last items routine $24 after

@return:				; CODE XREF: Ristar_SetLastTakenItemRoutine24+6j
		rts
