		beq.s	Ristar_ChkRistarWater_Return
		cmpi.b	#$13,d0		; Is Ristars subroutine	counter	13 (RistarSub12) if so return?
		beq.s	Ristar_ChkRistarWater_Return
		btst	#0,$4E(a0)	; Is Ristar in water?
		bne.s	Ristar_ChkRistarWater_Ristar_In_Water
