					; Ristar_ChkRistarWater+30j
		cmp.w	(WaterSurfaceYposWord).w,d0 ; Compare Ristars Y	position with that of the water	and if it is lower (above water) then return
		bcs.s	Ristar_ChkRistarWater_Return
		bset	#0,$4E(a0)	; Set Ristar in	water

Ristar_ChkRistarWater_Return:		; CODE XREF: Ristar_ChkRistarWater+4j
					; Ristar_ChkRistarWater+10j ...
