; =============== S U B	R O U T	I N E =======================================

; Takes	d1 collision array indexvar, d2	Ypos as	inputs and returns d3 as collision variable
; 0(a3)	Ristar collision angles
; 1(a3)	ColIndexStart
; 2(a3)	Secondary collision index

Collision_Down_PrimaryCollisionArray:	; CODE XREF: RistarMovingDown_ChkCollision+2Ap
					; RistarMovingDown_ChkCollision+42p ...
		bsr.w	Collision_PrimaryCollisionArray	; Inputs are d1	Xpos, d2 Ypos
					; Returns d0 from collision array, uses	d1 for collision array indexvar.
					; 0(a3)	Ristar collision angles
					; 1(a3)	ColIndexStart
					; 2(a3)	Secondary collision index
		tst.w	d0		; Can be from $F1 to $10
		beq.w	@NoCollision
		bmi.w	@NegativeCollision ; D0	was any	of $F1 - $FF
		cmpi.w	#$10,d0
		beq.s	@First_EQ_10
		move.w	d2,d5		; D0 was any of	1-$E so	we move	Ypos into d5
		andi.w	#$F,d5		; Filter out the lowest	4 bits
		add.w	d5,d0		; Add the filtered number (0-$F) to d0
		moveq	#$F,d3
		sub.w	d0,d3		; Subtract the resulting d0 from d3($F)	and return the resulting d3
		rts
; ---------------------------------------------------------------------------

@First_EQ_10:				; CODE XREF: Collision_Down_PrimaryCollisionArray+12j
		neg.w	d0

@NegativeCollision:			; CODE XREF: Collision_Down_PrimaryCollisionArray+Aj
		move.w	d2,d3		; Move Ypos into d3
		andi.w	#$F,d3		; Filter out the lowest	4 bits
		add.w	d3,d0		; Add the filtered number (0-$F) to d0
		bpl.w	@return		; If d0	is positive we return
		neg.w	d3		; Since	the result was negative	or zero	we negate d3
		subq.w	#1,d3		; And reduce d3	by 1
		subi.w	#$10,d2		; Decrease Ypos	by $10
		movem.l	d3,-(sp)	; Store	d3, d4,	d5 and d6 on the stack
		bsr.w	Collision_PrimaryCollisionArray	; Inputs are d1	Xpos, d2 Ypos
					; Returns d0 from collision array, uses	d1 for collision array indexvar.
					; 0(a3)	Ristar collision angles
					; 1(a3)	ColIndexStart
					; 2(a3)	Secondary collision index
		movem.l	(sp)+,d3
		tst.w	d0
		beq.w	@return
		sub.w	d0,d3
		rts
; ---------------------------------------------------------------------------

@return:				; CODE XREF: Collision_Down_PrimaryCollisionArray+2Cj
					; Collision_Down_PrimaryCollisionArray+46j
		rts
; ---------------------------------------------------------------------------

@NoCollision:				; CODE XREF: Collision_Down_PrimaryCollisionArray+6j
		move.w	d2,d5
		andi.w	#$F,d5
		moveq	#$F,d3
		sub.w	d5,d3
		addi.w	#$10,d2
		movem.l	d3,-(sp)
		bsr.w	Collision_PrimaryCollisionArray	; Inputs are d1	Xpos, d2 Ypos
					; Returns d0 from collision array, uses	d1 for collision array indexvar.
					; 0(a3)	Ristar collision angles
					; 1(a3)	ColIndexStart
					; 2(a3)	Secondary collision index
		movem.l	(sp)+,d3
		tst.w	d0
		beq.w	loc_1FC3C
		bmi.s	locret_1FC42
		moveq	#$10,d5
		sub.w	d0,d5
		add.w	d5,d3
		rts
; ---------------------------------------------------------------------------

loc_1FC3C:				; CODE XREF: Collision_Down_PrimaryCollisionArray+6Cj
		addi.w	#$10,d3
		rts
; ---------------------------------------------------------------------------

locret_1FC42:				; CODE XREF: Collision_Down_PrimaryCollisionArray+70j
		rts
; End of function Collision_Down_PrimaryCollisionArray


; =============== S U B	R O U T	I N E =======================================

; Inputs are d1	Xpos, d2 Ypos
; Returns d0 from collision array, uses	d1 for collision array indexvar.
; 0(a3)	Third collision	array variable
; 1(a2)	ColIndexStart
; 2(a3)	Secondary collisiion index
; Returns d3=0 No collision, other collision

Collision_Up_PrimaryCollisionArray:	; CODE XREF: Ristar_Jump_Collision_Check+14p
					; Ristar_Jump_Collision_Check+2Cp ...
		bsr.w	Collision_PrimaryCollisionArray	; Inputs are d1	Xpos, d2 Ypos
					; Returns d0 from collision array, uses	d1 for collision array indexvar.
					; 0(a3)	Ristar collision angles
					; 1(a3)	ColIndexStart
					; 2(a3)	Secondary collision index
		tst.w	d0
		beq.w	@NoCollision
		bmi.w	@NegativeCollision
		move.w	d2,d3		; Move Ypos into d3
		andi.w	#$F,d3		; Filter out the lowest	4 bits
		add.w	d3,d0		; Add the filtered number (0-$F) to d0
		subi.w	#$10,d0		; Decrease d0 by $10
		bmi.w	@return		; If it	it negative we return
		subi.w	#$10,d3		; It was not negative to we decrease the filtered by $10
		addi.w	#$10,d2		; And increase Ypos by $10
		movem.l	d3,-(sp)	; Store	the old	d3 to the stack
		bsr.w	Collision_PrimaryCollisionArray	; Inputs are d1	Xpos, d2 Ypos
					; Returns d0 from collision array, uses	d1 for collision array indexvar.
					; 0(a3)	Ristar collision angles
					; 1(a3)	ColIndexStart
					; 2(a3)	Secondary collision index
		movem.l	(sp)+,d3	; And restore the old d3 from the stack
		tst.w	d0
		beq.w	@NoCollision2
		bmi.w	@NegativeCollision2
		subi.w	#$10,d3		; We had positive collision again so we	increase the filtered Ypos by $10
		rts
; ---------------------------------------------------------------------------

@NoCollision2:				; CODE XREF: Collision_Up_PrimaryCollisionArray+34j
		rts
; ---------------------------------------------------------------------------

