		move.w	d1,$10(a2)
		move.b	d0,$E(a2)
		add.w	d0,d0
		add.w	d0,d0
		moveq	#0,d1
		move.w	(a1,d0.w),d1
		move.w	2(a1,d0.w),d0
		lsl.w	#4,d0
