		move.w	#0,$1C(a0)	; No side movement so Xspd 0

Obj044_RopeGrab_3_AlreadyRun:		; CODE XREF: Obj044_Index+4A2j
		cmpi.b	#1,$1E(a0)
		blt.s	Obj044_RopeGrab_3_Yspd_LT_1
		moveq	#0,d2
		move.b	$13(a0),d2
		move.w	$20(a0),d1
		add.w	$24(a0),d2
		lea	(CollisionHotspotLeftAngle).w,a3
		move.w	#$E,d7
		jsr	Collision_Down_PrimaryCollisionArray ; Takes d1	collision array	indexvar, d2 Ypos as inputs and	returns	d3 as collision	variable
					; 0(a3)	Ristar collision angles
					; 1(a3)	ColIndexStart
					; 2(a3)	Secondary collision index
		tst.w	d3
		ble.s	Obj044_RopeGrab_3_Skip

Obj044_RopeGrab_3_Yspd_LT_1:		; CODE XREF: Obj044_Index+4B6j
		addi.w	#$20,$1E(a0) ; ' '
