Obj044_RopeGrab_CheckWithinRange_WithinRange: ;	CODE XREF: Obj044_Index+4F8j
		lea	(Ristar_And_Object_RAM_Start).w,a1
		tst.b	(RistarHandsGoingOut).l	; Either 0 or 1
		beq.s	Obj044_RopeGrab_CheckWithinRange_Skip
		movem.w	(SomeXpos).w,d1-d2
		jsr	ChkRistarHandsOut_XposYpos ; Returns d5	= 0 or 1 (if both Xpos and Ypos	is negative
		tst.w	d5
