Obj03E_PricesFromObjects:		; DATA XREF: ROM:00003C78o
		lea	(LastObjectInTheList).w,a1 ; Used with SST going up to word $48
		jsr	(AddChildObject).l ; Input a1 =	d0 word	to 46(a6) from SuperTableIndexVar6 word	address	is saved to 48(a0)
		beq.w	Obj03E_PricesFromObjects_Return	; There	was no free slot so we return
		movea.l	a0,a2		; Move Obj03E to a2
		movea.l	a6,a3		; Move new child to a3
		move.w	#$F,d0

Obj03E_PricesFromObjects_CopyObjectLoop: ; CODE	XREF: Obj03E_PricesFromObjects+18j
		move.l	(a2)+,(a3)+	; Copy Obj03E 16 times
		dbf	d0,Obj03E_PricesFromObjects_CopyObjectLoop
		move.w	#$810C,(a6)	; Obj044_PricesFromObjects (10C) maybe
		moveq	#0,d0
		move.b	3(a6),d0	; Copy frame in	animation to d0
		cmpi.b	#2,(Ristar_Difficulty).w ; 0 = Normal (4 Star)
					; 1 = Hard (2 Star)
					; 2 = Super (1 Star)
		bne.s	Obj03E_PricesFromObjects_NotSuperDifficulty
		moveq	#2,d0

Obj03E_PricesFromObjects_NotSuperDifficulty: ; CODE XREF: Obj03E_PricesFromObjects+2Cj
		move.b	d0,$17(a6)
		move.b	$17(a6),d0
		lsl.w	#4,d0		; Multiply by 16 ($10) to get the correct index
		lea	(Obj03E_044_Settings_NormalDifficulty).l,a1
		adda.w	d0,a1
		move.l	(a1)+,8(a6)
		move.w	(a1)+,$E(a6)
		move.w	(a1)+,$36(a6)
		move.w	(a1)+,6(a6)
		move.b	(a1)+,$3E(a6)
		move.b	(a1)+,3(a6)
		move.b	(a1)+,5(a6)
		move.b	(a1)+,2(a6)
		move.b	(a1)+,$34(a6)
		move.b	$2C(a6),$2F(a6)
		bset	#4,2(a6)
		move.b	#4,$16(a6)
		movea.w	$4E(a0),a3
		move.w	#$FFFF,(a3)
		jmp	(InsertNewChildObjectA0).l ; Checks to see if there is anything	in $46(a0) and if so moves it into a6.
					; Then it copy whats in	$48(a0)	to $48(a6). $48(a0) is then moved to a5.
					; $46(a0) is then moved	to $46(a5). And	the last loaded	object is inserted into	$46(a0).
