; D0: Xpos
; D1: Ypos
; D2: Bit0 Ristar Xpos high byte set, Bit1 Object Ypos positive, Bit2 Xpos and Ypos swapped.

ChkRistarObject_XposYpos:		; CODE XREF: Obj032_Index+16Cp
					; Adahan_UpdateXspdYspd+8p ...
		moveq	#0,d2
		move.w	d0,d3		; Move Ristar Xpos into	d3
		eor.w	d5,d3		; Extended or it with object Xpos
		sub.w	d5,d0		; Subtract object Xpos from Ristars Xpos
		bcc.s	ChkRistarObject_XposYpos_RistarXposResultNegative
		andi.w	#$8000,d3	; Filter out the high byte of Ristar Xpos eor Object Xpos
		bne.s	ChkRistarObject_XposYpos_Skip ;	Skip if	high byte was set

ChkRistarObject_XposYpos_HighBitSetNegative: ; CODE XREF: ChkRistarObject_XposYpos+1Cj
		bset	#0,d2		; Set bit 0 of d2 if high byte was not set
		neg.w	d0		; Negate Ristar	Xpos - object Xpos so it is positive
		bra.s	ChkRistarObject_XposYpos_Skip
; ---------------------------------------------------------------------------

ChkRistarObject_XposYpos_RistarXposResultNegative: ; CODE XREF:	ChkRistarObject_XposYpos+8j
		andi.w	#$8000,d3	; Filter out the high byte of Ristar Xpos eor Object Xpos
