					; ChkRistarObject_XposYpos+16j
		sub.w	d6,d1		; Subtract object Ypos from Ristars Ypos
		bpl.s	ChkRistarObject_XposYpos_Skip2 ; Skip if result	is positive
		tst.w	d6
		bmi.s	ChkRistarObject_XposYpos_Skip2 ; Skip if objects Ypos was negative
		bset	#1,d2		; Objects Ypos was zero	or positive so we set bit 1 of d2
		neg.w	d1		; Negate Ristars Ypos -	objects	Ypos so	it becomes positive

ChkRistarObject_XposYpos_Skip2:		; CODE XREF: ChkRistarObject_XposYpos+20j
					; ChkRistarObject_XposYpos+24j
		cmp.w	d0,d1		; Compare (Ristar Xpos - object	Xpos) with (Ristar Ypos	- object Ypos)
		bcs.s	ChkRistarObject_XposYpos_Ypos_HS_Xpos
		bset	#2,d2		; Ypos was lower so we set bit 2 of d2
		exg	d0,d1		; And exchange Xpos and	Ypos to	get the	largest

ChkRistarObject_XposYpos_Ypos_HS_Xpos:	; CODE XREF: ChkRistarObject_XposYpos+2Ej
