; =============== S U B	R O U T	I N E =======================================

; Input	d1=Variable, a1	= Destination, a3=Source, a4=Source2

PalSwapColor:				; CODE XREF: GameMode04_TimeAttack+42p
					; GameMode04_TimeAttack+5Cp ...
		moveq	#$F,d0
		andi.w	#$FF,d1		; And 1111 1111	d1
		sub.w	d1,d0		; Subtract d1 from d0 $F (16)

PalSwapColor_FadeNextSlot:		; CODE XREF: PalSwapColor+94j
		move.w	(a4)+,d2	; FadePaletteRAM
		move.w	(a3)+,d3	; FadePalette
		lsl.w	#8,d0		; Multiply with	512 making everything 0	in first byte
		lsl.w	#8,d1		; Multiply with	512 making everything 0	in first byte
		move.w	d2,d4		; copy d2 to d4
		move.w	d3,d5		; copy d3 to d5
		andi.w	#$E00,d4	; And with 1110	0000 0000
		andi.w	#$E00,d5	; And with 1110	0000 0000
		cmp.w	d5,d4		; Is d4	greater	or even	to d5
		bge.s	PalSwapColor_D4_GE_D5_E00
		sub.w	d4,d5		; Else we subtract d4 from d5
		sub.w	d1,d5		; And d1 from d5 as well
		bpl.s	PalSwapColor_D5_Positive_E00
		moveq	#0,d5		; If it	was negative we	make d5	zero

PalSwapColor_D5_Positive_E00:		; CODE XREF: PalSwapColor+24j
		add.w	d5,d4		; Add d5 to d4
		bra.s	PalSwapColor_Continue0E0
; ---------------------------------------------------------------------------

PalSwapColor_D4_GE_D5_E00:		; CODE XREF: PalSwapColor+1Ej
		sub.w	d5,d4		; We subtract d5 from d4
		sub.w	d0,d4		; And d0 from d4 as well
		bpl.s	PalSwapColor_D4_PositiveE00
		moveq	#0,d4		; Else we make d4 zero

PalSwapColor_D4_PositiveE00:		; CODE XREF: PalSwapColor+30j
		add.w	d5,d4		; Add d5 to d4

PalSwapColor_Continue0E0:		; CODE XREF: PalSwapColor+2Aj
		move.w	d4,-(sp)	; Store	d4 on the stack
		lsr.w	#4,d0		; Divide with 16
		lsr.w	#4,d1		; Divide with 16
		move.w	d2,d4		; copy d2 to d4
		move.w	d3,d5		; copy d3 to d5
		andi.w	#$E0,d4	; 'à'   ; And with 1110 0000
		andi.w	#$E0,d5	; 'à'   ; And with 1110 0000
		cmp.w	d5,d4		; Is d4	greater	or even	to d5
		bge.s	PalSwapColor_D4_GE_D5_0E0
		sub.w	d4,d5		; Else we subtract d4 from d5
		sub.w	d1,d5		; And d1 from d5 as well
		bpl.s	PalSwapColor_D5_Positive_0E0
		moveq	#0,d5		; If it	was negative we	make d5	zero

PalSwapColor_D5_Positive_0E0:		; CODE XREF: PalSwapColor+50j
		add.w	d5,d4		; Add d5 to d4
		bra.s	PalSwapColor_Continue00E
; ---------------------------------------------------------------------------

PalSwapColor_D4_GE_D5_0E0:		; CODE XREF: PalSwapColor+4Aj
		sub.w	d5,d4		; We subtract d5 from d4
		sub.w	d0,d4		; And d0 from d4 as well
		bpl.s	PalSwapColor_D4_Positive0E0
		moveq	#0,d4		; Else we make d4 zero

PalSwapColor_D4_Positive0E0:		; CODE XREF: PalSwapColor+5Cj
		add.w	d5,d4		; Add d5 to d4

PalSwapColor_Continue00E:		; CODE XREF: PalSwapColor+56j
		lsr.w	#4,d0		; Divide with 16
		lsr.w	#4,d1		; Divide with 16
		move.w	d2,d5		; copy d2 to d5
		move.w	d3,d6		; copy d3 to d6
		andi.w	#$E,d5		; And with 1110
		andi.w	#$E,d6		; And with 1110
		cmp.w	d6,d5		; Is d6	greater	or even	to d5
		bge.s	PalSwapColor_D6_GE_D5_00E
		sub.w	d5,d6		; Else we subtract d5 from d6
		sub.w	d1,d6		; And we subtract d1 from d6
		bpl.s	PalSwapColor_D6_Positive00E
		moveq	#0,d6		; If d6	was negative we	make it	zero

PalSwapColor_D6_Positive00E:		; CODE XREF: PalSwapColor+7Aj
		add.w	d6,d5		; Add d6 to d5
		bra.s	PalSwapColor_ContinueEnd
; ---------------------------------------------------------------------------

PalSwapColor_D6_GE_D5_00E:		; CODE XREF: PalSwapColor+74j
		sub.w	d6,d5		; We subtract d6 from d5
		sub.w	d0,d5		; We subtract d0 from d5
		bpl.s	PalSwapColor_D5_Positive_00E
		moveq	#0,d5		; If d5	was negative we	make it	zero

PalSwapColor_D5_Positive_00E:		; CODE XREF: PalSwapColor+86j
		add.w	d6,d5		; Add d6 to d5

PalSwapColor_ContinueEnd:		; CODE XREF: PalSwapColor+80j
		or.w	d5,d4		; Or d5	with d4
		move.w	(sp)+,d6	; Restore d4 from stackpointer to d6
		or.w	d6,d4		; Or d6	with d4
		move.w	d4,(a1)+	; Move it to the Current slot in FadePaletteROM
		dbf	d7,PalSwapColor_FadeNextSlot ; Do for the other	number of slots
		rts			; Return
; End of function PalSwapColor


