; =============== S U B	R O U T	I N E =======================================

; Input:
; a2 = returned	as sinewave var	added to it
; a3 = returned	as the lowest three nibbles ored by the	highest	nibble after anding both
; d2 = bit to clear from FFE5A0

Camera_sub_55762:			; CODE XREF: Camera_sub_556A4+16p
					; Camera_sub_556A4+2Cp	...
		move.w	(a3),d0		; Move first word of a3	to d0
		move.w	d0,d1		; Copy it to d1
		andi.w	#$FFF,d0	; Filter out the 3 lowest bytes	of d0
		andi.w	#$F000,d1	; Filter out the highest byte of d1
		subq.w	#1,d0		; Decrease d0 by 1
		bne.s	Camera_sub_55762_D0_NE_Zero
		bclr	d2,(SomeSpecialCameraVar).w ; Object flags:
					; 0: Check none	gameplay index
					; 1: Set at game mode 4
					; 2: Set at game mode 4_5
					; 3: Set at Obj05D_7 Obj05D_IceSpikesMatSpike_5_1
					; 4: Set at GM04_5_4_Round6_2_5
					; 5: Ristar knocked out
					; 6: Unused
					; 7: Unused

Camera_sub_55762_D0_NE_Zero:		; CODE XREF: Camera_sub_55762+Ej
		or.w	d1,d0		; Or d0	(the lowest three nibbles -1) with d1 (highest nibble only)
		move.w	d0,(a3)		; Update a3 with d0
		andi.w	#7,d0		; Filter out the lowest	3 bits of d0
		rol.w	#7,d1		; Roll d1 to the left 7	steps making it	0000 0000 0111 1000
		add.w	d1,d0		; This seems a bit strange we add $78 to d0 which would	make the index far higher than $1F that	we want
		move.b	SineWave_FC_to_4(pc,d0.w),d0 ; -4,-2,-1,0,1,2,4
		ext.w	d0		; Extend d0 to a word
		add.w	d0,(a2)		; And add it to	a2
		rts
; End of function Camera_sub_55762

; ---------------------------------------------------------------------------
SineWave_FC_to_4:dc.b 1, 0, $FF, 0, 1, 0, $FF, 0, 1, 2,	1, 0, $FF, $FE,	$FF, 0
					; DATA XREF: Camera_sub_55762+20r
		dc.b 2,	0, $FE,	0, 2, 0, $FE, 0, 2, 4, 2, 0, $FE, $FC, $FE, 0

