Obj1D8_ChkPassword_CheckPassword:	; CODE XREF: Obj1D8_PasswordMenu+230j
		move.b	#$2D,d0	; '-'
		jsr	(CacheSound).l	; Password was correct play sound $2D
		move.w	#$20FF,(PasswordCharacter1).w ;	Fill all buffers with space and	end of text
		move.w	#$20FF,(PasswordCharacter2).w
		move.w	#$20FF,(PasswordCharacter3).w
		move.w	#$20FF,(PasswordCharacter4).w
		move.w	#$20FF,(PasswordCharacter5).w
		move.w	#$20FF,(PasswordCharacter6).w
		move.w	#0,(PasswordCharacterCounter).w
		move.b	(a4)+,d0
		asl.w	#8,d0		; Aritmic shift	left 256 (switch byte low to high)
		move.b	(a4)+,d0	; Insert next byte
		tst.w	d0
		bmi.s	Obj1D8_ChkPassword_D0_Negative
		move.w	d0,(CheatCode1).w ; 0: MAGURO (Onchi Setup)
					; 1: CANDY (INVINCIBLE)	(Japan only)
					; 2: ILOVEU (Level Select)
					; 3: MIEMIE (True Sight)
					; 4: AAAAAA (Free Continue) (Japanese only)
					; 5: SUPER  (Super mode)
					; 6: MUSEUM (Boss Rush)
					; 7: AGES   (Copyright Sega 1995)
		bra.w	Obj1D8_ChkPassword_Skip2
; ---------------------------------------------------------------------------

Obj1D8_ChkPassword_D0_Negative:		; CODE XREF: Obj1D8_PasswordMenu+2A6j
		asr.w	#8,d0		; Divide d0 by 256
		cmpi.b	#$FF,d0		; Check	if pass	is as Ages
		beq.w	Obj1D8_ChkPassword_Skip2 ; It was Ages
		cmpi.b	#$FE,d0
		beq.w	Obj1D8_ChkPassword_PassSuper
		cmpi.b	#$FD,d0
		beq.w	Obj1D8_ChkPassword_JapanesePassStar
		cmpi.b	#$FC,d0
		beq.w	Obj1D8_ChkPassword_JapanesePassValdi
		move.b	#$89,d0
		jsr	(CacheSound).l	; It was neither -1, -2, -3 or -4 os the password is Master
		bra.w	Obj1D8_ChkPassword_Skip2
; ---------------------------------------------------------------------------

