GM16_EndingCreditJap:			; DATA XREF: ROM:00055400o
		tst.b	(SomeMenuVar2).w ; FE: Start pressed at	best game time
					; FF: Set if start button is not pressed at menu
					; 0:
					; 1: Set at Obj1D4_5_1 RistarMenu
					; 2: Set at Obj1D4_7_3 RistarMenu
					; 3: Set if ValdiPass is active
					; Eyebar also uses it to store the Ypos
		beq.s	Load_Obj1D2_EndGameCredits
		move.w	#2,(GameModeSub).w ; Set round screen

Load_Obj1D2_EndGameCredits:		; CODE XREF: GM16_EndingCreditJap+4j
		move.b	(TempVarE688).w,d0
		tst.b	d0
