		cmp.b	(TempVarE68A).w,d0
		beq.w	GM16_EndingCreditJap_Return
		move.b	d0,(TempVarE68A).w
		move.b	d0,(TempVarE688).w
		lea	(LastObjectInTheList).w,a1 ; Used with SST going up to word $48
		jsr	(AddChildObject).l ; Input a1 =	d0 word	to 46(a6) from SuperTableIndexVar6 word	address	is saved to 48(a0)
		move.w	#$50,(a6) ; 'P' ; Obj1D2_EndGameCredits
		moveq	#0,d0
		move.b	(TempVarE688).w,d0
