SMPS_UpdateMusic:			; CODE XREF: j_UpdateMusicj
					; DATA XREF: ROM:000C803Co
		movem.l	d0-a6,-(sp)
		movea.l	pSoundStore,a6
		bsr.w	Sound_Play
		bsr.w	Sound_ChkValue
		tst.b	3(a6)
		bmi.w	SMPS_UpdateMusic_cleanexit
		bsr.w	SMPS_DoFade
		bsr.w	SMPS_TempoWait
		bsr.w	SMPS_DoFadeOut
		bsr.w	SMPS_UpdateEverything
		bsr.w	SMPS_OverrideFM4Frequency
		bsr.w	SMPS_DoTrackNoteCutoff
		tst.b	(PalModeFlag).l
		beq.w	SMPS_UpdateMusic_cleanexit
		cmpi.b	#5,$48(a6)
		beq.w	SMPS_UpdateMusic_do_double_update
		addq.b	#1,$48(a6)
		bra.w	SMPS_UpdateMusic_cleanexit
; ---------------------------------------------------------------------------

SMPS_UpdateMusic_do_double_update:	; CODE XREF: SMPS_UpdateMusic+40j
		move.b	#0,$48(a6)
		bsr.w	SMPS_DoFade
		bsr.w	SMPS_TempoWait
		bsr.w	SMPS_DoFadeOut
