		bsr.w	SMPS_OverrideFM4Frequency
		bsr.w	SMPS_DoTrackNoteCutoff

SMPS_UpdateMusic_cleanexit:		; CODE XREF: SMPS_UpdateMusic+14j
					; SMPS_UpdateMusic+36j	...
		movem.l	(sp)+,d0-a6
		rts
; End of function SMPS_UpdateMusic


